window.EXPL={"관세사2017_34-41":{"w":"2년간 이자비용 270,680 중 표시이자 지급분은 100,000×2=200,000이므로 할인차금 상각액은 70,680이다.\n20x3년 초 사채 장부금액 = 885,840 + 70,680 = 956,520\n상환이익 1,520이 있으므로 지급한 현금 = 956,520 - 1,520 = 955,000","c":"상"},"관세사2018_35-62":{"w":"발행금액 = 70,000×3.1699 + 1,000,000×0.6830 = 221,893 + 683,000 = 904,893 (①).\n20×1년 이자비용 90,489, 말 장부금액 904,893 + (90,489-70,000) = 925,382 (②, ③).\n20×2년 이자비용 925,382×10% = 92,538, 말 장부금액 947,920 (④).\n20×3년 이자비용 947,920×10% = 94,792이므로 95,792가 아니다. 따라서 ⑤가 옳지 않다.","c":"상"},"관세사2019_36-58":{"w":"②가 옳지 않다. 사채발행비는 발행금액에서 차감되어 실제 수령액이 줄어들기 때문에 유효이자율은 시장이자율보다 높아진다.\n① 총이자비용 = 액면이자 합계 + 할인차금이므로 맞다.\n③ 할증발행은 장부금액이 매년 줄어 이자비용도 감소한다.\n④ 할인발행은 상각액이 매년 커져 장부금액이 체증적으로 증가한다.\n⑤ 시장이자율이 유효이자율보다 커지면 사채의 시장가격이 장부금액보다 낮아 상환이익이 생긴다.","c":"상"},"관세사2019_36-62":{"w":"권면상 발행일(1/1)에 시장이자율 8%를 적용한 현재가치 = 50,000×2.5771 + 1,000,000×0.7938 = 128,855 + 793,800 = 922,655\n실제 발행일(7/1)까지 6개월 월할 이자 = 922,655×8%×6/12 = 36,906\n7/1 증가한 부채 = 922,655 + 36,906 = 959,561 (사채 934,561 + 경과이자 25,000)","c":"중"},"관세사2020_37-45":{"w":"ㄱ. 차입금은 현금을 인도할 계약상 의무이므로 금융부채이다.\nㄴ. 선수금은 제품을 인도할 의무이므로 금융부채가 아니다.\nㄷ. 고정 수량(5주)의 자기지분상품을 인도하므로 금융부채가 아니라 자본이다.\nㄹ. 보유자가 확정금액 상환을 청구할 수 있는 상환우선주는 금융부채이다.\n정답은 ㄱ, ㄹ이다.","c":"상"},"관세사2020_37-65":{"w":"20×1년 이자비용 11,400 = 95,000×유효이자율이므로 유효이자율은 12%이다.\n20×1년 말 장부금액 = 95,000 + (11,400-10,000) = 96,400\n20×2년 1/1~7/1 이자비용 = 96,400×12%×6/12 = 5,784\n7/1 이후 남은 액면 50,000분의 장부금액을 96,400의 절반인 48,200으로 보면 이자비용 = 48,200×12%×6/12 = 2,892\n합계 5,784 + 2,892 = 8,676","c":"중"},"관세사2022_39-56":{"w":"발행금액 = 3,000×2.7232 + 100,000×0.8638 = 8,170 + 86,380 = 94,550\n20×1년 말 장부금액 = 94,550 + (4,728-3,000) = 96,278\n20×2년 말 장부금액 = 96,278 + (4,814-3,000) = 98,092\n20×3년 초 장부금액 98,092를 95,000에 상환했으므로 상환이익 = 98,092 - 95,000 = 3,092","c":"상"},"관세사2022_39-60":{"w":"금융부채는 현금 등 금융자산을 인도할 계약상 의무이다.\n매입채무 3,000 + 장기차입금 10,000 + 미지급금 3,300 + 사채 15,000 + 미지급이자 8,000 = 39,300\n선수수익, 제품보증충당부채, 미지급법인세는 현금 지급 계약이 아니라서 제외한다.","c":"상"},"관세사2023_40-56":{"w":"발행금액 = 100,000×3.3121 + 1,000,000×0.7350 = 331,210 + 735,000 = 1,066,210\n20×1년 말 = 1,066,210 + (85,297-100,000) = 1,051,507\n20×2년 말 = 1,051,507 + (84,121-100,000) = 1,035,628","c":"상"},"관세사2023_40-58":{"w":"ㄱ. 외상 구입은 매입채무이므로 금융부채이다.\nㄴ. 임대료 선수분은 선수수익으로 용역을 제공할 의무이므로 금융부채가 아니다.\nㄷ. 계약금은 선수금으로 상품을 인도할 의무이므로 금융부채가 아니다.\nㄹ. 사채는 현금 지급 의무가 있는 금융부채이다.\n정답은 ㄱ, ㄹ이다.","c":"상"},"관세사2024_41-60":{"w":"20×1년 이자비용 92,416×10% = 9,242, 상각액 9,242-8,000 = 1,242, 장부금액 93,658\n20×2년 이자비용 9,366, 상각액 1,366, 장부금액 95,024\n20×3년 이자비용 95,024×10% = 9,502, 상각액 9,502-8,000 = 1,502","c":"상"},"관세사2025_42-52":{"w":"발행금액 = 10,000×6.0021 + 1,000,000×0.7599 = 60,021 + 759,900 = 819,921\n만기까지 총이자비용 = 액면이자 합계 + 할인차금 = 10,000×7 + (1,000,000-819,921) = 70,000 + 180,079 = 250,079","c":"중"},"관세사2025_42-53":{"w":"공정가치선택 금융부채는 공정가치 변동 중 자신의 신용위험 변동분 170,000을 기타포괄손익으로 인식하고, 나머지 130,000(300,000-170,000)은 당기손익으로 인식한다.\n부채 공정가치가 하락했으므로 당기순이익은 130,000 증가한다.","c":"상"},"관세사2025_42-55":{"w":"발행금액 = 2,000×3.5460 + 100,000×0.8227 = 7,092 + 82,270 = 89,362\n20×1년 말 91,830 → 20×2년 말 94,422 → 20×3년 말 97,143 (각 연도 이자비용 4,468, 4,592, 4,721 에서 액면이자 2,000을 뺀 값을 가산)\n20×4년 초 장부금액 97,143을 100,000에 상환하므로 상환손실 = 100,000 - 97,143 = 2,857","c":"상"},"관세사2025_42-56":{"w":"ㄱ. 선수금은 제품을 인도할 의무이므로 금융부채가 아니다.\nㄴ. 상품 구입 대금을 현금으로 지급할 의무는 금융부채이다.\nㄷ. 공정가치 300,000에 해당하는 수량의 자기지분상품을 인도하는 것은 인도 수량이 변동되므로 금융부채이다.\nㄹ. 소송 패소가능성이 높은 것은 충당부채 문제이며 금융부채가 아니다.\n정답은 ㄴ, ㄷ이다.","c":"상"},"관세사2026_43-52":{"w":"발행금액 = 5,000×2.5771 + 100,000×0.7938 = 12,886 + 79,380 = 92,266\n20×1년 말 94,647, 20×2년 말 97,218 (이자비용 7,381, 7,572에서 액면이자 5,000을 뺀 값을 가산)\n20×3년 1/1~7/1 이자비용 = 97,218×8%×6/12 = 3,889\n7/1 장부금액(미지급이자 포함) = 97,218 + 3,889 = 101,107\n98,000에 상환했으므로 상환이익 = 101,107 - 98,000 = 3,107","c":"상"},"관세사2026_43-53":{"w":"금융부채에 속하는 것은 매입채무 5,000, 차입금 12,000, 사채, 미지급이자 1,000이다.\n제품보증충당부채, 선수금, 선수수익, 당기법인세부채는 제외한다.\n5,000 + 12,000 + 사채 + 1,000 = 27,000이므로 사채 = 9,000","c":"상"},"관세사2026_43-54":{"w":"의무상환우선주는 금융부채이며 배당금은 이자비용이다.\n상환액 = 100주×1,500 = 150,000, 연 배당 = 100주×500×10% = 5,000\n발행 시 부채 = 5,000×2.4868 + 150,000×0.7513 = 12,434 + 112,695 = 125,129\n20×1년 이자비용 = 125,129×10% = 12,513","c":"상"},"관세사2026_43-61":{"w":"지분상품을 발행해 금융부채를 상환하면 발행한 지분상품의 공정가치(100주×7,000 = 700,000)와 부채 장부금액의 차이를 당기손익으로 인식한다.\n상환이익 = 1,000,000 - 700,000 = 300,000","c":"상"},"관세사2017_34-42":{"w":"결산승인 후 이익잉여금 = 300,000 - 자기주식처분손실 상각 10,000 - 현금배당 100,000 = 190,000\n임의적립금 이입, 이익준비금 적립은 이익잉여금 내부 항목 간 이동이라 총액이 변하지 않는다.\n자기주식처분손실 상각은 자본조정을 줄이면서 미처분이익잉여금을 같은 금액 감소시킨다.","c":"상"},"관세사2017_34-44":{"w":"1차 처분(10주×3,000): 처분이익 = (3,000-2,000)×10 = 10,000\n2차 처분(20주×500): 처분손실 = (2,000-500)×20 = 30,000\n처분손실은 먼저 처분이익과 상계하므로 자기주식처분손실 = 30,000 - 10,000 = 20,000","c":"상"},"관세사2017_34-48":{"w":"20x1년 누적 보상원가 = 100명×(1-10%)×6개×10×1/3 = 1,800\n20x2년 누적 보상원가 = 100명×(1-15%)×6개×10×2/3 = 3,400\n공정가치는 부여일 기준 10을 쓴다.\n20x2년 주식보상비용 = 3,400 - 1,800 = 1,600","c":"상"},"관세사2018_35-50":{"w":"①이 옳지 않다. 무액면주식은 발행가액 중 이사회가 정한 금액을 자본금으로 하므로 발행하면 자본금이 증가한다.\n②는 자본총액이 시가총액과 일치하지 않는 것이 일반적이므로 맞고, ③은 잔여지분의 정의, ④는 무상증자와 형식적 감자가 자본 구성만 바꾸는 점, ⑤는 자본이 재무상태 측정요소인 점에서 맞다.","c":"상"},"관세사2018_35-64":{"w":"3/10 자기주식 취득: -100×3,000 = -300,000\n6/30 처분: +50×3,600 = +180,000\n10/13 소각: 자본총액 변화 없음\n11/30 유상증자: +50×4,000 - 35,000 = +165,000\n12/31 총포괄이익: +200,000 + 130,000 = +330,000\n합계 = -300,000 + 180,000 + 165,000 + 330,000 = 375,000","c":"상"},"관세사2018_35-67":{"w":"①이 옳지 않다. 측정기준일은 부여일인 20×1년 1월 1일이다.\n③ 20×1년 주식보상비용 = 50명×90%×10개×500×1/2 = 112,500\n②가득기간 2년, ④부여일, ⑤주식결제형은 모두 맞다.","c":"상"},"관세사2019_36-42":{"w":"주식발행초과금 = (6,000-5,000)×1,000주 + (7,000-5,000)×1,000주 = 1,000,000 + 2,000,000 = 3,000,000\n주식발행과 직접 관련된 원가 500,000은 주식발행초과금에서 차감하고, 간접 관련 원가 200,000은 당기비용이다.\n보고할 주식발행초과금 = 3,000,000 - 500,000 = 2,500,000","c":"상"},"관세사2019_36-43":{"w":"취득: -200주×4,000 = -800,000\n4월 처분: +50주×5,000 = +250,000\n9월 처분: +50주×3,500 = +175,000\n자본총액 변동 = -800,000 + 250,000 + 175,000 = -375,000 (감소)\n기말 공정가치는 자기주식을 평가하지 않으므로 영향이 없다.","c":"상"},"관세사2019_36-47":{"w":"①이 옳지 않다. 무상증자, 주식배당, 주식분할, 주식병합은 모두 자본 항목 간 이동이나 주식수 변경만 있고 자본총계는 변하지 않는다.\n②무상증자와 주식배당은 자본금이 늘어난다. ③주식배당과 주식분할은 자본잉여금이 변하지 않는다. ④주식배당은 이익잉여금이 자본금으로 옮겨가고 주식분할은 이익잉여금이 그대로다. ⑤주식수는 앞의 셋이 늘고 병합은 줄어든다.","c":"상"},"관세사2019_36-61":{"w":"성과조건은 가득될 수량에 반영하고 단위당 공정가치는 부여일 600을 계속 쓴다.\n20×1년: 100개×600×1/2 = 30,000\n20×2년 말 실제 가득 300개: 누적 보상원가 300×600 = 180,000\n20×2년 비용 = 180,000 - 30,000 = 150,000","c":"상"},"관세사2020_37-51":{"w":"현금결제형 주가차액보상권은 매 보고기간 말 공정가치로 부채를 재측정하며, 20×2년 말은 가득 시점이므로 가득한 수량 전부를 부채로 인식한다.\n가득 수량 = 94명×50개 = 4,700개\n단위당 공정가치를 500으로 하면 부채 = 4,700×500 = 2,350,000 (선지 ④와 일치)\n문제 자료에 단위당 공정가치가 빠져 있어, 선지 간격을 보고 500으로 역산했다.","c":"중"},"관세사2020_37-55":{"w":"우선주 자본금 = 200주×500 = 100,000, 연 배당률 4% 이므로 연 4,000.\n누적적이므로 20×1~20×4년 4년분 4,000×4 = 16,000을 먼저 받는다.\n부분참가 한도 7%에서 기본 4%를 뺀 3%의 참가분은 100,000×3% = 3,000 이하로 제한된다. 보통주 배당률 4%(250,000×4% = 10,000)를 먼저 주고 남은 24,000을 자본금 비율로 나누면 우선주 몫이 한도 3,000을 넘지 않는 범위에서 3,000이다.\n우선주 = 16,000 + 3,000 = 19,000\n보통주 = 50,000 - 19,000 = 31,000","c":"중"},"관세사2020_37-64":{"w":"기초 290,000\n3/30 현금배당 -100,000 (주식배당은 자본총계 불변)\n6/9 자기주식 취득 -50주×800 = -40,000\n7/13 재발행 +20주×900 = +18,000\n12/13 유상증자 +50주×1,000 = +50,000\n기말 = 290,000 - 100,000 - 40,000 + 18,000 + 50,000 = 218,000","c":"상"},"관세사2022_39-67":{"w":"결산 승인 전 미처분이익잉여금 43,000\n+ 임의적립금 이입 3,000\n- 주식할인발행차금 상각 2,000\n- 현금배당 10,000\n= 차기이월미처분이익잉여금 34,000\n자료에 이익준비금 적립이 없으므로 더 차감하지 않는다.","c":"상"},"관세사2022_39-68":{"w":"우선주 자본금 100,000(200주×500), 5% → 연 5,000. 설립 후 처음 배당이므로 20×1~20×3년 3년분 누적 15,000을 받는다.\n보통주 자본금 150,000(300주×500), 5% → 7,500\n잔여 = 38,000 - 15,000 - 7,500 = 15,500\n완전참가이므로 자본금 비율 100,000:150,000 = 2:3으로 나눠 우선주 6,200, 보통주 9,300\n우선주 배당금 = 15,000 + 6,200 = 21,200","c":"상"},"관세사2023_40-44":{"w":"20×1년 말: 누적 영업이익 성장률 평균 (22%+예상 20%)/2 = 21% ≥ 20% → 2년 가득 예상. 퇴사 8명 + 예상 6명 = 14명 → 86명.\n누적 보상원가 = 86×20×1,000×1/2 = 860,000\n20×2년 말: 실제 16%라 2년 평균 19%로 20% 미달 → 3년 평균 (22+16+8)/3 = 15.3% ≥ 15%이므로 3년 가득 예상. 퇴사 8+5 = 13명 + 예상 3명 = 16명 → 84명.\n누적 보상원가 = 84×20×1,000×2/3 = 1,120,000\n20×2년 보상비용 = 1,120,000 - 860,000 = 260,000","c":"상"},"관세사2023_40-49":{"w":"①현금배당 결의로 이익잉여금이 줄고 미지급배당금(부채)이 늘어 자본이 감소한다.\n②자기주식 재발행은 현금 유입으로 자본 증가, ③신주발행도 증가이다.\n④무상감자는 자본금이 줄고 결손금이 같은 금액 줄어 자본총계 불변, ⑤적립금 간 대체도 불변이다.","c":"상"},"관세사2023_40-55":{"w":"기초 2,000,000\n자기주식 취득 -10주×700 = -7,000\n주식배당 0 (자본 내부 이동)\n유상증자 +100주×800 - 5,000 = +75,000\n자기주식 재발행 +6주×600 = +3,600\n현물출자 +55,000 (토지 공정가치)\n포괄이익 +200,000 - 10,000 = +190,000\n기말 = 2,000,000 - 7,000 + 75,000 + 3,600 + 55,000 + 190,000 = 2,316,600","c":"상"},"관세사2024_41-54":{"w":"④가 옳다. 가득은 권리를 획득하는 것이며 가득조건에는 용역제공조건과 성과조건이 있다.\n①현금결제형은 부채 증가를 인식한다. ②내재가치 = 기초주식 공정가치 - 행사가격 = 20-30으로 음수여서 10이 아니다. ③현금결제형의 공정가치 변동은 당기손익이다. ⑤종업원 거래는 부여일, 종업원 외 거래는 재화·용역을 제공받는 날이 측정기준일로 ⑤는 둘이 바뀌어 있다.","c":"상"},"관세사2024_41-55":{"w":"⑤가 옳지 않다. 미지급배당금은 배당기준일이 아니라 주주총회에서 배당을 결의한 날 대변에 기록한다. 배당기준일에는 분개가 없다.\n①할증발행의 분개 ②신주발행비는 발행금액에서 차감 ③재발행 금액과 취득원가의 차이는 자기주식처분손익 ④유상감자 대가가 액면에 미달하면 감자차익(자본잉여금)이다.","c":"상"},"관세사2024_41-59":{"w":"20×1년 말 미처분이익잉여금 = 150 + 4,000 = 4,150\n+ 배당평균적립금 이입 500 = 4,650\n- 현금배당 50,000×3% = 1,500\n- 이익준비금 적립 1,500×1/10 = 150\n- 주식배당 300\n- 사업확장적립금 100\n= 차기이월미처분이익잉여금 2,600","c":"상"},"관세사2024_41-65":{"w":"기초 50,000\n2/28 현금배당 -2,000 (주식배당은 불변)\n5/15 자기주식 취득 -20주×150 = -3,000\n7/17 유상증자 +100주×200 = +20,000\n9/10 무상증자 0\n10/5 자기주식 매각 +10주×180 = +1,800\n11/11 소각 0\n기말 = 50,000 - 2,000 - 3,000 + 20,000 + 1,800 = 66,800","c":"상"},"관세사2025_42-58":{"w":"현금 유입 = 500주×1,500 = 750,000, 직접 관련 원가 30,000을 차감하면 순유입 720,000이다.\n기존 주식할인발행차금 60,000은 자본 항목 안에서 상계되어 자본총계에 영향이 없다.\n자본총계 720,000 증가","c":"상"},"관세사2025_42-59":{"w":"40주를 주당 800에 처분하면 현금이 40×800 = 32,000 들어와 자본이 32,000 증가한다(취득원가 500은 취득 시 이미 차감됨).\n10주 소각은 자본 내부 이동이라 자본총계에 영향이 없다.\n총 영향 = 32,000 증가","c":"상"},"관세사2025_42-60":{"w":"우선주 자본금 100,000, 6% → 연 6,000, 누적 20×1~20×3년 3년분 18,000.\n보통주 자본금 400,000, 5% → 20,000\n잔여 = 45,000 - 18,000 - 20,000 = 7,000\n자본금 비율 400:100으로 참가하면 우선주 몫 7,000×1/5 = 1,400이며, 부분참가 한도 (8%-6%)×100,000 = 2,000 이내이다.\n우선주 배당금 = 18,000 + 1,400 = 19,400","c":"상"},"관세사2025_42-62":{"w":"기초 자본 = 22,000-16,000 = 6,000, 기말 자본 = 26,000-17,000 = 9,000\n자본 증가 3,000 = 당기순이익 - 자기주식 300 - 현금배당 400 + 토지재평가잉여금 100\n(무상증자와 주식배당은 자본총계 불변)\n당기순이익 = 3,000 + 300 + 400 - 100 = 3,600","c":"상"},"관세사2025_42-69":{"w":"20×1년 말 누적 보상원가 = 100명×80%×10개×30×1/3 = 8,000\n20×2년 말 누적 보상원가 = 100명×90%×10개×30×2/3 = 18,000\n20×2년 보상비용 = 18,000 - 8,000 = 10,000","c":"상"},"관세사2026_43-58":{"w":"취득: -200주×6,000 = -1,200,000\n5/1 처분: +70주×12,000 = +840,000\n6/1 처분: +80주×15,000 = +1,200,000\n7/1 소각은 자본총액 변화가 없다.\n합계 = -1,200,000 + 840,000 + 1,200,000 = 840,000 증가","c":"상"},"관세사2026_43-65":{"w":"②가 옳다. 지분상품이 부여 즉시 가득되면 반증이 없는 한 용역 전부를 부여일에 보상비용으로 인식하고 자본을 같은 금액 증가시킨다.\n①재화·용역의 공정가치를 추정할 수 없으면 지분상품의 공정가치로 측정한다. ③시장조건은 공정가치 측정에 반영하고 가득수량 조정에는 쓰지 않는다. ④공정가치 측정은 가득일까지, 내재가치 측정은 결제일까지 인식하는 것으로 ④는 반대다. ⑤내재가치로 측정하면 가득 후 소멸 시 이미 인식한 금액을 환입한다.","c":"중"},"관세사2017_34-43":{"w":"이자수익 = 95,434×15% = 14,315\n20×1년 말 상각후원가 = 95,434 + 14,315 - 13,000 = 96,749\n공정가치 95,000이므로 기타포괄손실 = 95,000 - 96,749 = -1,749\n총포괄이익 = 14,315 - 1,749 = 12,566","c":"상"},"관세사2017_34-50":{"w":"20x1년 말 장부금액 = 915,000×(1+r) - 50,000 = 938,200\n915,000×(1+r) = 988,200이므로 1+r = 1.08, 유효이자율 r = 8%","c":"상"},"관세사2019_36-52":{"w":"이자수익 = 110,812×12% = 13,297\n20×1년 말 상각후원가 = 110,812 + 13,297 - 15,000 = 109,109\n공정가치 95,000이므로 기타포괄손실 = 109,109 - 95,000 = 14,109","c":"상"},"관세사2019_36-54":{"w":"(A) 당기손익-공정가치: 거래원가 2,000은 당기비용, 취득 공정가치 50,000, 20×1년 말 49,000으로 평가손실 1,000. 처분 51,000 - 49,000 = 처분이익 2,000.\n(B) 기타포괄손익-공정가치 지분: 평가손익은 기타포괄손익이고 처분손익은 당기손익에 반영하지 않는다. 처분으로 인한 당기손익은 0이다.\n정답은 (A) 이익 2,000, (B) 0이다.","c":"상"},"관세사2020_37-50":{"w":"③이 옳지 않다. 기타포괄손익-공정가치에서 상각후원가로 재분류할 때는 공정가치로 측정한 뒤, 기타포괄손익누계액을 자본에서 제거하고 재분류일 공정가치에서 조정한다. 당기손익으로 인식하지 않는다.\n①④ 상각후원가 → 당기손익/기타포괄손익-공정가치 재분류는 공정가치로 측정하고 차이를 각각 당기손익/기타포괄손익으로 인식한다. ② 당기손익-공정가치 → 상각후원가는 공정가치가 새 총장부금액이다. ⑤ 계속 공정가치로 측정한다.","c":"상"},"관세사2020_37-53":{"w":"취득금액 45,900에서 20×1년 말 상각후원가가 46,613이 되려면 유효이자율이 7%이어야 한다: 45,900×1.07 - 2,500 = 46,613.\n20×2년 이자수익 = 상각후원가(20×1년 말) 46,613×7% = 3,263\n공정가치 변동은 이자수익에 영향이 없다.","c":"상"},"관세사2022_39-64":{"w":"4/1 취득: 거래원가 1,500은 비용, 취득 공정가치 40,000 (주당 800)\n6/9 처분: 30주×(900-800) = 이익 3,000\n12/31 평가: 20주×(700-800) = 손실 2,000\n당기손익 = -1,500 + 3,000 - 2,000 = -500 (손실 500)","c":"상"},"관세사2022_39-65":{"w":"⑤가 옳지 않다. 기업이 자기지분상품을 재취득하면 그 금액을 자본에서 차감하며 금융자산으로 인식하지 않는다.\n①~④는 금융상품, 금융자산, 금융부채의 정의와 발행자의 분류 원칙을 그대로 말한 것이다.","c":"상"},"관세사2022_39-70":{"w":"상각후원가 측정 금융자산은 공정가치가 아니라 유효이자율법으로 장부금액을 정한다.\n20×1년 이자수익 = 90,490×10% = 9,049\n20×1년 말 장부금액 = 90,490 + 9,049 - 7,000 = 92,539\n공정가치 92,000은 장부금액에 영향이 없다.","c":"상"},"관세사2023_40-60":{"w":"당기손익-공정가치 측정 금융자산의 거래수수료 1,000은 취득 시 당기비용이고 최초 장부금액은 10,000이다.\n20×1년 말 공정가치 9,000으로 평가한다.\n20×2년 처분이익 = 11,000 - 9,000 = 2,000","c":"상"},"관세사2023_40-61":{"w":"이자수익 = 875,640×10% = 87,564\n20×1년 말 상각후원가 = 875,640 + 87,564 - 50,000 = 913,204\n공정가치 950,000이므로 기타포괄이익 = 950,000 - 913,204 = 36,796","c":"상"},"관세사2024_41-44":{"w":"지급보증 한도가 300이고 양도한 자산의 장부금액이 500이므로 지속관여자산은 둘 중 작은 300이다.\n지속관련부채 = 지급보증금액 300 + 지급보증의 공정가치 100 = 400\n2/1에 보증의무 200을 이행하면 지급한 200 중 지급보증 공정가치 100을 차감한 100이 비용으로 남는다.\n(가) 400, (나) 100","c":"중"},"관세사2025_42-50":{"w":"거래원가 200주×50 = 10,000은 취득 시 비용이다.\n배당금수익 200주×30 = 6,000\n처분이익 100주×(1,200-1,050) = 15,000, 처분 거래원가 100주×50 = 5,000 비용\n무상증자로 받은 20주는 회계처리가 없고 주식수만 늘어난다.\n기말 보유 120주 평가: 공정가치 120×1,300 = 156,000, 장부금액 100주×1,050 = 105,000, 평가이익 51,000 (예상 처분원가는 반영하지 않는다)\n당기순이익 영향 = -10,000 + 6,000 + 15,000 - 5,000 + 51,000 = 57,000 증가","c":"상"},"관세사2026_43-49":{"w":"취득 거래원가 5,000은 비용\n처분이익 = 30주×(1,800-1,000) = 24,000, 처분 거래원가 3,000은 비용\n기말 평가이익 = 20주×(1,500-1,000) = 10,000\n당기순이익 증가액 = -5,000 + 24,000 - 3,000 + 10,000 = 26,000","c":"상"},"관세사2017_34-45":{"w":"만기금액 = 200,000×(1+8%×6/12) = 208,000\n3개월 보유 후 할인 시 남은 기간은 3개월이므로 할인료 = 208,000×12%×3/12 = 6,240, 현금 수령액 = 201,760\n보유 3개월분 이자수익 = 200,000×8%×3/12 = 4,000, 어음 장부금액 = 204,000\n처분손실 = 204,000 - 201,760 = 2,240\n당기순이익 영향 = 이자수익 4,000 - 처분손실 2,240 = 1,760 증가","c":"상"},"관세사2018_35-52":{"w":"매출원가 = 16,000 + 32,000 - 22,000 = 26,000\n매출액 = 매출원가 26,000 + 매출총이익 13,000 = 39,000\n외상매출 = 39,000 - 현금매출 7,000 = 32,000\n기말 매출채권 = 10,000 + 32,000 - 40,000 = 2,000","c":"상"},"관세사2019_36-50":{"w":"현금및현금성자산 = 국내통화 1,200 + 외국환 통화(€1, $1의 원화 환산액) + 보통예금 1,800 + 우편환 200 + 취득일 만기 3개월 이내 환매채 400\n수입인지, 선일자수표, 급여가불증, 1년 만기 정기예금, 사용이 제한된 양도성예금증서는 제외한다.\n원문 자료에 환율이 빠져 있어, 선지 ④ 6,100에서 역산하면 외국환 환산액은 2,500이고 합계 1,200 + 2,500 + 1,800 + 200 + 400 = 6,100이다.","c":"하"},"관세사2020_37-41":{"w":"ㄱ. 송금환은 통화대용증권이라 현금이다.\nㄴ. 타인발행약속어음은 받을어음(매출채권 등)이다.\nㄷ. 우표는 선급비용이나 소모품이다.\nㄹ. 만기가 도래한 국채이자표는 통화대용증권이라 현금이다.\nㅁ. 정기예금은 취득일 기준 만기가 3개월 이내여야 현금성자산인데 2월 초 취득이라 해당하지 않는다.\n정답은 ㄱ, ㄹ이다.","c":"상"},"관세사2020_37-42":{"w":"손실충당금 변동: 기초 5,000 - 제각 7,000 + 회수 3,000 + 손상차손 = 기말 6,000\n제각한 채권을 회수하면 손실충당금이 늘어난다.\n손상차손 = 6,000 - (5,000 - 7,000 + 3,000) = 5,000","c":"상"},"관세사2020_37-52":{"w":"만기금액 = 120,000×(1+10%×6/12) = 126,000\n2개월 보유 후 할인하므로 남은 4개월의 할인료 = 126,000×12%×4/12 = 5,040, 현금 수령액 120,960\n보유 2개월 이자수익 = 120,000×10%×2/12 = 2,000, 어음 장부금액 122,000\n처분손실 = 122,000 - 120,960 = 1,040\n당기손익 = 이자수익 2,000 - 처분손실 1,040 = 960 이익","c":"상"},"관세사2022_39-48":{"w":"②가 옳지 않다. 12개월 이내에 기한이 도래하지 않으면서 사용이 제한된 예금은 유동자산이 아니라 비유동자산(장기금융상품 등)이다.\n①우선주 중 상환일이 정해진 단기 상품은 현금성자산에 포함될 수 있고, ③은 단기금융자산, ④⑤는 현금성자산의 정의와 취득시 만기 3개월 이내 기준에 맞다.","c":"상"},"관세사2022_39-52":{"w":"회사 장부 잔액 18,000을 조정한다.\n- 은행수수료 800 (장부 미반영) → -800\n- 어음 추심입금 6,000 (미통지) → +6,000\n- 부도수표 1,500 (미통지) → -1,500\n조정 후 정확한 잔액 = 18,000 - 800 + 6,000 - 1,500 = 21,700\n미인출수표 2,000은 은행에서 아직 빠져나가지 않았으므로 은행 잔액에 2,000이 더 남아 있다.\n은행 잔액 = 21,700 + 2,000 = 23,700","c":"상"},"관세사2022_39-59":{"w":"팩토링은 제거요건을 충족하지 못하므로 차입거래로 처리하고 매출채권처분손익이 생기지 않는다(수수료 2,000은 처분손실이 아니다).\n어음할인은 제거요건을 충족하므로 3/1에 만기까지 남은 2개월의 할인료가 처분손실이다. 무이자부 어음이라 이자수익이 없다.\n처분손실 = 200,000×9%×2/12 = 3,000","c":"중"},"관세사2023_40-62":{"w":"만기금액 = 100,000×(1+12%×3/12) = 103,000\n1개월 보유 후 할인하므로 남은 2개월 할인료 = 103,000×15%×2/12 = 2,575, 현금 수령액 100,425\n어음 장부금액 = 100,000 + 100,000×12%×1/12 = 101,000\n처분손실 = 101,000 - 100,425 = 575","c":"상"},"관세사2024_41-43":{"w":"현금 200 + 타인발행수표 600 + 배당금지급통지서 500 + 우편환증서 200 = 1,500 (통화와 통화대용증권)\n선일자수표는 매출채권이고, 당좌개설보증금은 사용이 제한된 장기금융상품이라 제외한다.","c":"상"},"관세사2025_42-45":{"w":"만기금액 = 2,400,000×(1+6%×6/12) = 2,472,000\n4개월 보유 후 할인하므로 남은 기간은 2개월이다.\n할인액 = 2,472,000 - 2,439,040 = 32,960\n32,960 = 2,472,000×r×2/12이므로 r = 8%","c":"상"},"관세사2026_43-48":{"w":"만기금액 = 120,000×(1+8%×4/12) = 123,200\n2개월 보유 후 할인하므로 남은 2개월의 할인료 = 123,200×10%×2/12 = 2,053, 현금 수령액 121,147\n어음 장부금액 = 120,000 + 120,000×8%×2/12 = 121,600\n처분손실 = 121,600 - 121,147 = 453","c":"상"},"관세사2017_34-46":{"w":"과세소득 = 240,000 + 접대비 한도초과 20,000 + 감가상각비 한도초과 40,000 = 300,000\n당기법인세 = 300,000×20% = 60,000\n접대비 한도초과는 영구적 차이라 이연법인세가 없다. 감가상각비 한도초과 40,000은 소멸 때 적용될 세율 30%로 이연법인세자산 40,000×30% = 12,000을 인식한다.\n법인세비용 = 60,000 - 12,000 = 48,000","c":"상"},"관세사2018_35-56":{"w":"과세소득 = 1,000,000 + 차감할 일시적차이 200,000 = 1,200,000\n당기법인세 = 1,200,000×25% = 300,000\n이연법인세자산 = 200,000×35% = 70,000 (소멸 시점 세율)\n법인세비용 = 300,000 - 70,000 = 230,000","c":"상"},"관세사2019_36-60":{"w":"과세소득 = 1,000,000 - 50,000 + 130,000 = 1,080,000\n법인세비용은 당기법인세에 이연법인세 변동을 반영한다. 일시적차이 순증가 80,000에 대한 이연법인세자산이 늘어 당기법인세 상당액이 법인세비용에서 빠지므로, 법인세비용은 법인세비용차감전순이익 1,000,000에 세율을 곱한 값과 같다.\n세율을 20%로 보면 법인세비용 = 1,000,000×20% = 200,000 (당기법인세 216,000, 이연법인세자산 증가 16,000)\n문제 자료에 세율이 빠져 있어, 선지 ③ 200,000과 선지 ④ 216,000 의 관계에서 20%로 확인했다.","c":"중"},"관세사2020_37-57":{"w":"⑤가 옳다. 자산이나 부채를 최초로 인식하는 시점에도 장부금액과 세무기준액이 달라 일시적차이가 생길 수 있다.\n①영업권 최초 인식에서 생기는 일시적차이는 이연법인세를 인식하지 않는다. ②이연법인세는 할인하지 않는다. ③소급공제가 가능한 세무상결손금의 혜택은 자산으로 인식한다. ④이연법인세자산은 회수 가능성이 낮아지면 장부금액을 감액한다.","c":"상"},"관세사2022_39-57":{"w":"②가 옳지 않다. 자산의 장부금액이 세무기준액보다 크면 미래에 과세소득에 가산될 일시적차이(가산할 일시적차이)이고, 이는 이연법인세부채를 발생시킨다.\n①소급공제 혜택은 자산, ③이연법인세부채의 정의, ④기대 세율로 측정, ⑤회수 가능성이 높아지면 인식하지 않았던 이연법인세자산을 인식한다.","c":"상"},"관세사2024_41-53":{"w":"ㄱ. 법인세비용은 당기법인세와 이연법인세로 구성된다.\nㄴ. 당기법인세자산과 부채의 상계는 법적으로 집행가능한 상계권리가 있고 순액으로 결제하거나 동시에 실현할 의도가 있는 경우에 한한다. 두 요건을 '또는'으로 쓴 문장은 틀리다.\nㄷ. 이연법인세자산의 장부금액은 매 보고기간 말에 검토한다.\nㄹ. 이연법인세는 할인하지 않는다.\n정답은 ㄱ, ㄷ이다.","c":"중"},"관세사2024_41-66":{"w":"법인세비용 1,500 = 당기법인세비용 + 이연법인세비용\n이연법인세자산 증가 200은 이연법인세비용 -200, 이연법인세부채 증가 100은 +100이므로 이연법인세비용은 -100이다.\n당기법인세비용 = 1,500 + 100 = 1,600\n납부액 = 당기법인세비용 1,600 - 당기법인세부채 증가 500 = 1,100","c":"상"},"관세사2025_42-64":{"w":"20×2년 당기법인세 = 120,000×20% = 24,000\n차감할 일시적차이 잔액: 20×1년 말 50,000-20,000 = 30,000, 20×2년 말 30,000-10,000 = 20,000\n이연법인세자산: 20×1년 말 30,000×20% = 6,000, 20×2년 말 20,000×25% = 5,000 (바뀐 세율)\n이연법인세자산이 1,000 줄었으므로 이연법인세비용 +1,000\n법인세비용 = 24,000 + 1,000 = 25,000","c":"상"},"관세사2026_43-64":{"w":"20×2년 당기법인세 = 과세소득 240,000×20% = 48,000\n이연법인세부채: 20×1년 말 가산할 일시적차이 20,000×20% = 4,000, 20×2년 말 일시적차이(B) 30,000×18% = 5,400\n이연법인세부채 증가 1,400 → 이연법인세비용 +1,400\n법인세비용 = 48,000 + 1,400 = 49,400","c":"상"},"관세사2017_34-47":{"w":"시가(2,000)보다 낮은 1,200에 발행했으므로 무상증자 요소가 있어 기초분 주식수를 조정한다.\n이론적 권리락 주가 = (2,000×1,400 + 1,200×1,000)/2,400 = 1,666.67\n조정계수 = 2,000/1,666.67 = 1.2\n가중평균유통보통주식수 = 1,400×1.2×3/12 + 2,400×9/12 = 420 + 1,800 = 2,220\n기본주당이익 = (350,000 - 비누적적 우선주 배당 17,000)/2,220 = 150\n보통주 배당금 120,000은 계산에 쓰지 않는다.","c":"상"},"관세사2018_35-54":{"w":"기초 유통보통주식수 = 발행 300주 - 자기주식 100주(100,000/1,000) = 200주\n7/1 자기주식 50주를 처분(재발행)하면 유통주식이 250주가 된다.\n가중평균 = 200 + 50×6/12 = 225주\n기본주당이익 = 720,000/225 = 3,200","c":"상"},"관세사2019_36-41":{"w":"④가 옳지 않다. 보통주로 반드시 전환해야 하는 전환금융상품은 전환시점이 아니라 계약이 체결된 시점부터 기본주당이익의 보통주식수에 포함한다.\n①~③, ⑤는 기준서 문장 그대로 맞다.","c":"상"},"관세사2020_37-59":{"w":"4/1 무상증자 25%는 기초로 소급한다: 10,000×1.25 = 12,500주\n7/1 유상증자 5,000주×6/12 = +2,500주\n10/1 자기주식 취득 1,000주×3/12 = -250주\n가중평균유통보통주식수 = 12,500 + 2,500 - 250 = 14,750","c":"상"},"관세사2022_39-69":{"w":"설립시 주식수를 N으로 두면 가중평균 = (N + 400×6/12)×1.1 (10/1 무상증자 10%는 전 기간에 소급)\n기본주당이익 200 = 264,000/가중평균이므로 가중평균 = 1,320주\n1.1×(N+200) = 1,320 → N = 1,000주","c":"상"},"관세사2023_40-50":{"w":"유상증자 1,000주를 발행금액 2,000, 직전 공정가치 2,500으로 보면(선지 ③과 맞물리는 값):\n이론적 권리락 주가 = (2,500×3,200 + 2,000×1,000)/4,200 = 2,380.95, 조정계수 = 2,500/2,380.95 = 1.05\n가중평균 = 3,200×1.05×6/12 + 4,200×6/12 - 800×3/12 = 1,680 + 2,100 - 200 = 3,580주\n기본주당이익 = 1,253,000/3,580 = 350\n문제에서 유상증자 주식수가 빠져 있어 1,000주로 역산했다.","c":"중"},"관세사2024_41-49":{"w":"4/1 유상증자: 이론적 권리락 주가 = (150×800 + 100×300)/1,100 = 136.36, 조정계수 = 150/136.36 = 1.1\n1/1~3/31: 800×1.1×3/12 = 220\n4/1~8/31: 1,100×5/12 = 458.3\n9/1~12/31: (1,100+x)×4/12\n합계 1,095이므로 (1,100+x)/3 = 1,095 - 220 - 458.3 = 416.7 → x = 150주","c":"상"},"관세사2025_42-57":{"w":"주식배당 10%는 전 기간에 소급하되, 이후에 일어난 10/1 자기주식 취득은 소급하지 않는다.\n기초 4,000주 + 4/1 유상증자 2,000주×9/12 = 1,500주 → 5,500주를 10% 소급하면 6,050주\n10/1 자기주식 취득 -200주×3/12 = -50주\n가중평균 = 6,050 - 50 = 6,000주\n기본주당이익 = 1,800,000/6,000 = 300","c":"상"},"관세사2026_43-59":{"w":"주주우선배정 유상증자는 시가보다 낮은 발행가라 무상증자 요소가 있다.\n이론적 권리락 주가 = (2,000×9,000 + 1,000×2,000)/11,000 = 1,818.18, 조정계수 = 2,000/1,818.18 = 1.1\n가중평균 = 9,000×1.1×3/12 + 11,000×9/12 = 2,475 + 8,250 = 10,725주\n기본주당이익 = 19,305,000/10,725 = 1,800","c":"상"},"관세사2017_34-49":{"w":"수정 후 금액을 정리한다.\n- 미수이자 600: 자산 +600, 수익 +600\n- 미지급이자 800: 부채 +800, 비용 +800\n- 선급보험료 중 당기분 300(1,200-900): 자산 -300, 비용 +300\n- 임대료 중 다음 기간분 1,600(2,400-800): 부채(선수수익) +1,600, 수익 -1,600\n자산 20,300, 부채 17,400, 수익 7,000, 비용 6,100이므로 당기순이익 = 7,000 - 6,100 = 900","c":"상"},"관세사2017_34-51":{"w":"⑤가 옳지 않다. 개념체계는 기준서가 아니므로 개념체계와 특정 기준서가 상충하면 해당 기준서가 우선한다.\n①~④는 개념체계의 목적(기준 제정 지원, 작성자 지원, 이용자 해석 지원, 감사인 의견 형성 지원)에 맞다.","c":"상"},"관세사2017_34-52":{"w":"④가 옳지 않다. 상법 등에서 이익잉여금처분계산서를 요구하는 경우 별도 보충명세서가 아니라 주석으로 공시한다.\n①~③, ⑤는 주석의 역할과 배당 공시 내용에 맞다.","c":"중"},"관세사2017_34-54":{"w":"⑤가 옳지 않다. 자산과 부채의 일부를 유동/비유동 구분법으로, 나머지는 유동성 순서로 표시하는 혼합 표시방법도 허용된다(사업 성격이 다른 영업을 영위하는 경우 등).\n②이연법인세자산(부채)은 유동으로 분류하지 않는다. ④보고기간 후 12개월 이상 차환할 재량권이 있으면 비유동부채로 분류한다.","c":"상"},"관세사2017_34-55":{"w":"①이 옳다. 부적절한 회계정책은 공시나 주석, 보충자료로 설명해도 정당화되지 않는다.\n②현금흐름 정보는 발생기준이 아니다. ③재고자산평가충당금 차감 표시는 상계가 아니다. ④52주 보고기간도 허용된다. ⑤준수 사실은 주석에 명시적이고 제한 없이 기재할 수 있다.","c":"상"},"관세사2017_34-56":{"w":"유동비율 200%, 당좌비율 100%이므로 유동자산 = 2×유동부채이고 당좌자산 = 유동부채이다.\n- 단기차입금 10,000 현금 상환: 유동자산, 유동부채가 같이 10,000 감소한다. 유동비율은 2배에서 (2L-10,000)/(L-10,000)으로 커지고, 당좌비율도 L-10,000/(L-10,000)보다 커진다.\n- 매출채권 현금 회수: 당좌자산 안에서 이동이므로 변화 없음.\n- 상품 외상판매: 재고자산이 당좌자산(매출채권)으로 바뀌어 당좌비율이 커지고 유동비율은 변하지 않는다.\n두 비율 모두 증가","c":"중"},"관세사2017_34-57":{"w":"보고기간후사건은 보고기간 말부터 재무제표 발행승인일까지 일어난 사건이다. 발행승인일은 이사회가 승인한 20x2년 3월 16일이다.\n따라서 20x1년 12월 31일과 20x2년 3월 16일 사이이다.","c":"상"},"관세사2018_35-41":{"w":"①이 옳지 않다. 서로 다른 관찰자가 어떤 서술이 충실하게 표현되었다는 데 의견이 일치하는 것은 검증가능성의 설명이다. 이해가능성은 정보를 명확하고 간결하게 분류하고 표시하는 것이다.\n②~⑤는 근본적·보강적 질적 특성과 목적적합성, 적시성의 설명에 맞다.","c":"상"},"관세사2018_35-42":{"w":"①이 옳지 않다. 대손충당금 같은 평가충당금을 차감해 순액으로 측정하는 것은 상계표시가 아니다.\n②~⑤는 총포괄손익, 계속기업 평가기간(12개월), 재분류조정, 주석의 정의에 맞다.","c":"상"},"관세사2018_35-43":{"w":"②가 옳지 않다. 기능별 분류(매출원가 등으로 나누는 방법)가 자의적인 배분과 상당한 판단이 더 필요하다. 성격별 분류는 배분이 필요 없어 적용이 간단하다.","c":"상"},"관세사2018_35-46":{"w":"①이 옳지 않다. 재무자본유지개념은 특정 측정기준을 요구하지 않고 역사적원가나 현행원가 어느 쪽으로도 적용할 수 있다. 현행원가 기준이 필요한 것은 실물자본유지 쪽이다.","c":"상"},"관세사2018_35-47":{"w":"ㄱ. 재고자산 도난은 유동자산 감소이다.\nㄴ. 차량 취득과 어음 발행은 비유동자산 증가와 부채 증가라 유동자산에는 영향이 없다.\nㄷ. 건물을 담보로 차입하면 현금이 늘어 유동자산이 증가한다.\nㄹ. 사채를 현금으로 상환하면 현금이 줄어든다.\nㅁ. 주식 발행 대금 현금 납입은 유동자산이 증가한다.\n정답은 ㄷ, ㅁ이다.","c":"상"},"관세사2018_35-68":{"w":"자기자본이익률 = 당기순이익 168,750 / 평균자본 375,000 = 45% (20×1년 말과 20×2년 말 자본이 모두 375,000)\n20×2년 말 유동비율 = 유동자산 300,000 / 유동부채 120,000 = 250%","c":"상"},"관세사2019_36-48":{"w":"재분류조정이 가능한 기타포괄손익은 ㄷ 해외사업장환산외환차이, ㄹ 기타포괄손익-공정가치 측정 채무상품 평가손익이다.\nㄱ 확정급여제도 재측정요소와 ㄴ 재평가잉여금은 후속적으로 당기손익으로 재분류되지 않는다.","c":"상"},"관세사2019_36-49":{"w":"②가 옳다. 투자자산과 영업용자산을 포함한 비유동자산의 처분손익은 처분대가에서 장부금액과 처분비용을 차감한 순액으로 표시한다.\n①기준서는 재무제표에 적용하며 모든 정보에 적용하는 것이 아니다. ③청산 의도가 있으면 계속기업 전제로 작성하지 않는다. ④일부만 준수했다면 준수 사실을 기재할 수 없다. ⑤표시방법 변경은 지속될 가능성이 높을 때 한다.","c":"상"},"관세사2019_36-51":{"w":"①이 옳지 않다. 목적적합성과 표현충실성이 없는 정보는 보강적 질적 특성이 있더라도 유용하지 않다.\n⑤처럼 근본적 질적 특성만으로도 유용할 수 있고, 보강적 특성은 그 유용성을 높일 뿐이다.","c":"상"},"관세사2019_36-53":{"w":"매출원가 = 1,000 + 8,500 - 2,000 = 7,500\n① 재고자산회전율 = 7,500/평균재고 1,500 = 5회로 8회보다 낮다.\n② 유동비율 기초 3,500/1,000 = 350%, 기말 3,000/1,500 = 200%로 기말이 낮다.\n③ 당좌비율 기초 (3,500-1,000)/1,000 = 250%, 기말 (3,000-2,000)/1,500 = 66.7%로 기초가 높다.\n④ 매출총이익률 = (10,000-7,500)/10,000 = 25%\n⑤ 유동비율은 당좌비율보다 크다.\n옳은 것은 ③이다.","c":"상"},"관세사2019_36-55":{"w":"①이 옳지 않다. 일반목적재무보고서는 이용자가 필요로 하는 모든 정보를 제공할 수 없고 제공하지도 않는다.\n④경영진은 내부에서 정보를 얻을 수 있어 일반목적재무보고서에 의존할 필요가 없다는 설명은 개념체계 문장 그대로다.","c":"상"},"관세사2019_36-56":{"w":"재무자본유지(불변구매력 단위): 기초 자본 100,000을 물가상승률 25%만큼 늘려 125,000을 유지해야 한다.\n기말 자본: 재고 15개를 판매하여 재고가 없으므로 현금 145,000 (100,000 - 75,000 + 120,000)\n이익 = 145,000 - 125,000 = 20,000","c":"상"},"관세사2019_36-63":{"w":"④는 보통주 발행으로 자산(현금)과 자본이 증가한다.\n①사채발행은 자산과 부채(사채)가 같이 늘고, ②상품권 발행은 현금과 선수금(부채), ③차입은 현금과 차입금, ⑤건물 외상구입은 건물과 미지급금이 증가한다.","c":"상"},"관세사2020_37-60":{"w":"①은 보고기간 후에 발생한 상황(투자자산 공정가치 하락)이므로 수정을 요하지 않는 보고기간후사건이다.\n②~⑤는 보고기간말에 이미 존재했던 상황을 확인하는 사건(취득원가·매각대가 확정, 소송 확정, 상여금 확정, 부정·오류 발견)이라 수정을 요한다.","c":"상"},"관세사2020_37-61":{"w":"⑤가 옳지 않다.\n총자산영업이익률: (주)관세 300,000/2,500,000 = 12%, (주)한국 450,000/3,000,000 = 15%로 3%p 낮다(5%가 아니다).\n① 매출액순이익률: 관세 250/640 = 39.1%, 한국 300/600 = 50%\n② 자기자본회전율: 관세 640/1,600 = 0.4회, 한국 600/1,000 = 0.6회\n③ 이자보상비율: 관세 300/40 = 7.5, 한국 450/100 = 4.5\n④ 관세의 자기자본이익률 (250-50)/1,600 = 12.5%, 한국 30%이고 총자산회전율은 관세 0.256, 한국 0.2","c":"상"},"관세사2022_39-45":{"w":"유동자산 = 유동부채 10,000×150% = 15,000\n총자산 = 15,000 + 비유동자산 45,000 = 60,000\n총부채 = 60,000 - 자기자본 15,000 = 45,000\n부채비율 = 45,000/15,000 = 300%","c":"상"},"관세사2022_39-46":{"w":"①이 옳지 않다. 재고자산평가충당금이나 대손충당금 같은 평가충당금을 차감해 순액으로 측정하는 것은 상계표시가 아니다.\n②국제회계기준 준수 사실은 주석으로 공시할 수 있고, ③현금흐름 정보 외에는 발생기준, ④부적절한 회계정책은 주석으로 정당화되지 않으며, ⑤비교정보는 전기 금액을 표시한다.","c":"상"},"관세사2022_39-47":{"w":"설명은 검증가능성이다. 서로 독립된 관찰자들이 표현충실성에 대해 합의에 이를 수 있다는 것이 검증가능성의 정의이다.","c":"상"},"관세사2023_40-41":{"w":"예측가치, 확인가치가 있으면 의사결정에 차이를 만들 수 있다는 것은 근본적 질적특성인 목적적합성의 설명이다.","c":"상"},"관세사2023_40-42":{"w":"시장참여자 관점에서 자산·부채를 측정하며, 시장참여자가 경제적으로 최선의 행동을 한다는 가정을 쓰는 측정기준은 공정가치이다.","c":"상"},"관세사2023_40-46":{"w":"⑤가 옳다. 주석은 실무적으로 적용 가능한 한 체계적인 방법으로 표시한다.\n①이연법인세자산은 유동자산으로 분류하지 않는다. ②영업주기는 자산 취득부터 현금 회수까지의 기간이다. ③특별손익 항목은 표시할 수 없다. ④성격별 분류 기업이 아니라 기능별 분류 기업이 성격별 추가 정보를 공시한다.","c":"상"},"관세사2023_40-53":{"w":"당좌비율 100%이므로 유동부채 = 당좌자산 200\n총자산 = 유동자산(200+100) + 비유동자산 700 = 1,000\n총부채 = 200 + 400 = 600, 기말 자본 = 400\n기초 자본 = 기말 400 - 당기순이익 160 = 240, 평균자본 = 320\n자기자본이익률 = 160/320 = 50%","c":"상"},"관세사2023_40-54":{"w":"거래 전: 당좌비율 2,000/1,500 = 133%, 유동비율 3,000/1,500 = 200%\n거래 후 당좌자산 = 2,000 + 400 (토지 처분 현금) - 700 (재고 현금 지급) = 1,700 (매출채권 회수는 당좌자산 안의 이동)\n재고자산 = 1,000 + 900 = 1,900, 유동부채 = 1,500 + 200 = 1,700\n당좌비율 1,700/1,700 = 100%로 감소, 유동비율 3,600/1,700 = 212%로 증가","c":"상"},"관세사2024_41-42":{"w":"⑤가 옳지 않다. 보고기간 후 재무제표 발행승인일 전에 상환을 요구하지 않기로 합의해도, 보고기간말에 대여자가 즉시 상환을 요구할 수 있었다면 유동부채로 분류한다. 비유동으로 분류하려면 보고기간말 이전에 합의가 있어야 한다.","c":"상"},"관세사2024_41-46":{"w":"①이 옳지 않다. 공정가치는 측정일에 시장참여자 사이의 정상거래에서 자산을 매도할 때 받거나 부채를 이전할 때 지급하게 될 가격, 즉 유출가격이다. 유입가격이 아니다.","c":"상"},"관세사2024_41-47":{"w":"평균 매출채권 = (100+150)/2 = 125\n매출채권회전율 = 외상매출액 200/125 = 1.6회\n평균회수기간 = 360일/1.6 = 225일","c":"상"},"관세사2024_41-61":{"w":"수정을 요하는 사건은 보고기간말에 이미 존재한 상황을 확인해 주는 사건이다.\nㄷ. 보고기간말에 존재한 현재의무가 소송 확정으로 확인되는 경우\nㅁ. 재무제표가 부정확하다는 것을 보여주는 부정이나 오류의 발견\nㄱ, ㄴ, ㄹ은 보고기간 후에 발생한 상황이어서 수정하지 않고 주석으로 공시한다.","c":"상"},"관세사2024_41-69":{"w":"①이 옳지 않다. 지배기업 소유주와 비지배지분에 귀속되는 총포괄손익은 자본변동표에 표시한다.\n②회계정책 변경의 소급적용 영향도 자본변동표에 표시한다.","c":"중"},"관세사2025_42-41":{"w":"①이 옳지 않다. 중립적 정보는 재무정보의 선택이나 표시에 편의가 없는 정보이다. 목적이 없거나 행동에 영향이 없는 정보를 뜻하지 않으며, 목적적합한 정보는 행동에 영향을 줄 수 있다.","c":"상"},"관세사2025_42-42":{"w":"⑤가 옳지 않다. 자산의 사용과 궁극적 처분으로 얻을 현금흐름의 현재가치는 사용가치이다. 이행가치는 부채를 이행할 때 이전해야 하는 현금 등의 현재가치이다.","c":"상"},"관세사2025_42-43":{"w":"①이 옳다. 동일 거래에서 발생하는 수익과 관련 비용의 상계표시가 거래의 실질을 반영하면 상계하여 표시한다.\n②부적절한 회계정책은 주석으로 정당화되지 않고, ③이연법인세자산은 유동자산으로 분류하지 않으며, ④총포괄손익은 소유주와의 거래로 인한 자본변동을 제외하고, ⑤일반목적재무제표는 특수보고서를 요구할 위치에 있지 않은 이용자의 정보요구를 위한 것이다.","c":"상"},"관세사2025_42-70":{"w":"20×1년 말 총부채 = 2×자기자본(E)이므로 총자산 = 3E\n20×2년 말 총자산 = 3E + 200,000 (부채·자본 각 100,000 증가)\n평균총자산 = 3E + 100,000 = 480,000/1.2 = 400,000이므로 E = 100,000\n20×2년 말 총부채 = 200,000+100,000 = 300,000, 자기자본 = 100,000+100,000 = 200,000\n부채비율 = 300,000/200,000 = 150%","c":"상"},"관세사2026_43-41":{"w":"①이 옳지 않다. 경제적자원과 청구권은 재무성과뿐 아니라 주식 발행, 채무증권 발행 같은 다른 사건이나 거래로도 변동된다.","c":"상"},"관세사2026_43-43":{"w":"ㄱ. 중요하지 않은 항목은 유사한 항목과 통합하여 표시할 수 있다.\nㄴ. 경영진은 계속기업 존속가능성을 평가한다.\nㄷ. 부적절한 회계정책은 공시나 주석으로 정당화되지 않는다.\nㄹ. 재고자산평가충당금 차감은 상계표시가 아니다.\n정답은 ㄱ, ㄴ이다.","c":"상"},"관세사2026_43-44":{"w":"⑤가 옳지 않다. 공정가치는 거래원가를 반영하지 않는다(자산 취득 시 거래원가로 증가하지 않고, 부채 인수 시 거래원가로 감소하지 않는다). 거래원가가 영향을 주는 것은 역사적원가와 현행원가이다.","c":"상"},"관세사2017_34-53":{"w":"②가 옳지 않다. 고정제조간접원가는 정상조업도에 기초해 배부하고, 비정상적으로 많은 생산이 이루어진 기간에만 실제조업도에 기초해 배부하여 단위당 원가가 낮아지게 한다. 문장의 정상조업도와 실제조업도가 바뀌어 있다.","c":"중"},"관세사2017_34-58":{"w":"매출액 = 현금수입 645,000 - 매출채권 감소 6,000 + 선수수익 감소 3,000 = 642,000\n매입액 = 현금지출 428,000 + 매입채무 증가 6,000 = 434,000\n매출원가 = 기초재고 50,000 + 매입 434,000 - 기말재고 55,000 = 429,000\n매출총이익 = 642,000 - 429,000 = 213,000","c":"상"},"관세사2017_34-59":{"w":"총평균단가 = (10,000+48,000)/(20+80) = 580\n매출원가 = 90개×580 = 52,200\n기말 장부수량 10개 중 실사 8개이므로 재고감모 2개×580 = 1,160 (비용)\n8개의 순실현가능가치 480이 원가 580보다 낮으므로 평가손실 8×(580-480) = 800\n비용총액 = 52,200 + 1,160 + 800 = 54,160","c":"상"},"관세사2018_35-44":{"w":"⑤가 옳지 않다. 원가측정방법으로 쓸 수 있는 것은 표준원가법과 소매재고법이고, 매출총이익법은 포함되지 않는다.\n④완성될 제품이 원가 이상으로 판매되면 투입할 원재료는 감액하지 않는다.","c":"중"},"관세사2018_35-57":{"w":"실사금액 1,000,000에 창고 밖에 있지만 아직 회사 소유인 재고를 더하고 창고에 있으나 회사 소유가 아닌 재고를 뺀다.\n- FOB 선적지 인도조건으로 출하해 운송 중인 상품은 이미 판매되었으므로 가산하지 않는다.\n- 위탁품 적송 300,000 중 미판매 70% = 210,000 가산\n- FOB 도착지 조건으로 매입해 운송 중인 상품은 아직 소유가 아니므로 가산하지 않는다.\n- 시송품 200,000 중 매입의사 미통보 40% = 80,000 가산\n재고자산 = 1,000,000 + 210,000 + 80,000 = 1,290,000","c":"상"},"관세사2018_35-60":{"w":"확정판매계약 40단위: 순실현가능가치 = 690 (판매비용 없음), 원가 700 → 평가손실 40×(700-690) = 400\n나머지 60단위: 순실현가능가치 = 750-80 = 670, 원가 700 → 평가손실 60×(700-670) = 1,800\n재고자산평가손실 = 400 + 1,800 = 2,200","c":"상"},"관세사2019_36-44":{"w":"선입선출 저가기준 소매재고법은 기초재고를 원가율에서 제외하고, 분모에 순인상은 더하며 순인하는 빼지 않는다.\n당기 매입원가 = 6,000,000 + 200,000 - 400,000 = 5,800,000\n원가율 = 5,800,000/(9,800,000+200,000) = 58%\n판매가능 판매가 = 2,100,000 + 9,800,000 + 200,000 - 100,000 = 12,000,000\n기말 판매가 = 12,000,000 - 매출 10,000,000 - 종업원할인 500,000 = 1,500,000\n기말재고 원가 = 1,500,000×58% = 870,000\n매출원가 = 1,400,000 + 5,800,000 - 870,000 = 6,330,000","c":"상"},"관세사2019_36-45":{"w":"④가 옳지 않다. 표준원가법은 평가 결과가 실제 원가와 유사한 경우에 사용할 수 있다.","c":"상"},"관세사2019_36-46":{"w":"순매출 = 450,000 - 50,000 = 400,000\n매출원가 = 400,000×(1-25%) = 300,000\n순매입 = 250,000 - 30,000 = 220,000\n기말재고 = 기초 150,000 + 순매입 220,000 - 매출원가 300,000 = 70,000","c":"상"},"관세사2020_37-44":{"w":"기말재고자산 10,000에는 수탁품 300이 들어 있어 회사 재고가 아니다. 정확한 기말재고 = 9,700\n매출원가 = 10,000 + 29,800 - 9,700 = 30,100\n판매 전 보관을 위한 창고비용 500은 재고 원가에 포함되지 않는 비용이라 판매비와관리비 10,000을 그대로 쓴다.\n세전이익 = 60,000 - 30,100 - 10,000 = 19,900\n당기순이익 = 19,900×(1-40%) = 11,940","c":"상"},"관세사2020_37-47":{"w":"②가 옳지 않다. 저가법은 항목별로 적용하는 것이 원칙이고, 재고자산의 분류나 특정 영업부문에 속하는 모든 재고자산에 기초해 적용하는 것은 적절하지 않다.\n③ 상황이 해소되면 최초 장부금액(원가)을 한도로 환입, ④ 평가손실과 모든 감모손실은 발생 기간의 비용으로 인식한다.","c":"상"},"관세사2020_37-58":{"w":"비정상파손은 원가 100, 판매가 400을 매입에서 빼고 원가율을 구한다. 저가기준 선입선출이므로 기초재고는 제외하고 순인하는 분모에서 뺀다.\n원가율 = (20,000-100)/(40,000+200-400) = 19,900/39,800 = 50%\n기말 판매가 = 기초 10,000 + 매입 40,000 + 순인상 200 - 순인하 300 - 비정상파손 400 - 정상파손 100 - 매출 30,000 = 19,400\n기말재고원가 = 19,400×50% = 9,700\n매출원가 = 기초 7,000 + 매입 20,000 - 비정상파손 100 - 9,700 = 17,200","c":"중"},"관세사2020_37-66":{"w":"판매가능원가 = 2,000 + 6,000 + 4,000 + 5,000 = 17,000 (④), 판매수량 총 400개, 기말 100개\n①이 옳지 않다. 계속기록법 이동평균법: 1/5 후 단가 8,000/300 = 26.67 → 4/3 후 12,000/400 = 30 → 4/20에 300개 판매(9,000) 잔 100개 3,000 → 5/19 매입 후 8,000/200 = 40 → 5/20에 100개 판매(4,000) → 기말 4,000이다(3,400이 아니다).\n② 가중평균 단가 17,000/500 = 34, 매출원가 400×34 = 13,600\n③ 선입선출 기말 100개 = 최근 매입 100×50 = 5,000\n⑤ 계속기록법 선입선출 매출원가 = (100×20+200×30) + 100×40 = 8,000 + 4,000 = 12,000","c":"상"},"관세사2022_39-41":{"w":"실사금액 15,000\n+ 위탁적송품 미판매분 3,000 (수탁자 창고에 있어도 회사 재고)\n+ 시송품 매입의사 미표시분 4,000\n+ 선적지인도 조건으로 매입해 운송 중인 상품 4,000 (선적 시점에 소유권 이전)\n선적지인도 조건으로 판매해 운송 중인 상품은 이미 판매되었으므로 더하지 않는다.\n기말재고자산 = 15,000 + 3,000 + 4,000 + 4,000 = 26,000","c":"상"},"관세사2022_39-42":{"w":"수량: 300+450-600+300-300 = 150개가 기말에 남는다.\n선입선출: 기말 150개는 최근 매입분 150×180 = 27,000\n총평균법: 평균단가 = (45,000+74,250+54,000)/1,050 = 165, 기말재고 150×165 = 24,750\n차이 = 27,000 - 24,750 = 2,250","c":"중"},"관세사2022_39-43":{"w":"비정상파손은 원가 350, 판매가 500을 먼저 차감한다.\n원가 합계 = 44,500+105,000-350 = 149,150\n판매가 합계 = 70,000+140,000+7,000-3,500-500 = 213,000 (원가기준이므로 순인하도 차감)\n원가율 = 149,150/213,000 = 약 70%\n기말 판매가 = 213,000 - 정상파손 1,500 - 매출 112,000 = 99,500\n기말재고원가 = 99,500×70% = 69,650","c":"중"},"관세사2022_39-44":{"w":"재고자산회전율 6회 = 매출원가/평균재고 3,600 → 매출원가 21,600\n매출총이익 = 40,000 - 21,600 = 18,400","c":"상"},"관세사2023_40-64":{"w":"저가기준 평균원가법은 원가율의 분모에 순인상은 더하고 순인하는 빼지 않는다. 비정상파손은 원가·판매가 모두 먼저 차감하고, 정상파손은 원가율에 영향을 주지 않고 판매가에서만 차감한다.\n원가 합계 = 50,000+112,500-1,000 = 161,500\n판매가 합계(순인하 제외) = 60,000+170,000+20,000-1,500 = 248,500\n원가율 = 161,500/248,500 = 약 65%\n기말 판매가 = 248,500 - 순인하 10,000 - 정상파손 7,500 - 매출 130,000 = 101,000\n기말재고원가 = 101,000×65% = 65,650","c":"중"},"관세사2023_40-65":{"w":"상품 40개(확정판매): 순실현가능가치 = 18,000(판매비용 없음), 평가손실 (20,000-18,000)×40 = 80,000\n상품 10개(일반판매): 순실현가능가치 = 17,000×(1-10%) = 15,300, 평가손실 (20,000-15,300)×10 = 47,000\n원재료: 완성될 제품이 원가 이상으로 판매될 것이므로 감액하지 않는다.\n평가손실 = 80,000 + 47,000 = 127,000","c":"상"},"관세사2023_40-66":{"w":"④가 옳지 않다. 원가가 순실현가능가치보다 높은 재고자산은 저가법을 반드시 적용해 평가손실을 인식해야 하며, 선택 사항이 아니다.","c":"상"},"관세사2024_41-58":{"w":"순매출액 = 6,000 - 500 = 5,500\n매출원가 = 5,500 - 매출총이익 1,125 = 4,375\n순매입액 = 3,750 - 250 = 3,500\n기초재고 = 매출원가 4,375 + 기말재고 375 - 순매입 3,500 = 1,250","c":"상"},"관세사2025_42-46":{"w":"20×1년 매출원가 = 1,000+8,000-3,000 = 6,000, 매출총이익 4,000, 매출총이익률 40%\n20×2년 매출원가 = 12,000×60% = 7,200\n20×2년 판매가능상품 = 3,000+8,000 = 11,000\n소실된 기말재고 = 11,000 - 7,200 = 3,800","c":"상"},"관세사2025_42-47":{"w":"제품: 순실현가능가치 = 3,400-200 = 3,200 ≥ 원가 3,000이므로 평가손실이 없다. 제품이 원가 이상으로 팔리므로 원재료도 감액하지 않는다.\n상품: 순실현가능가치 = 4,500-100 = 4,400 < 원가 5,000, 평가손실 (5,000-4,400)×2,500 = 1,500,000\n재고자산평가손실 = 1,500,000","c":"상"},"관세사2026_43-42":{"w":"매출원가 = 매출액 40,000 - 매출총이익 14,800 = 25,200\n평균재고 = (2,000+3,600)/2 = 2,800\n재고자산회전율 = 25,200/2,800 = 9회","c":"상"},"관세사2026_43-51":{"w":"감모수량 50개×1,200 = 60,000, 이 중 정상 80% = 48,000(매출원가), 비정상 20% = 12,000(기타비용)\n실사수량 350개의 원가 420,000, 순실현가능가치 350×1,050 = 367,500이므로 평가손실 52,500, 기말 장부금액 367,500\n매출원가 = 기초 40,000 + 매입 500,000 - 기말 원가 420,000 - 비정상감모 12,000 = 108,000, 평가손실 52,500을 포함하면 160,500이다.\n①의 172,500은 비정상감모 12,000까지 더한 값이라 옳지 않다.","c":"상"},"관세사2017_34-60":{"w":"회계정책 변경은 소급적용하여 비교기간(20x2년)을 재작성한다.\n20x2년 기말재고 차이 = 5,600 - 5,000 = +600, 기초재고(20x1년 말) 차이 = 4,800 - 4,500 = +300\n20x2년 당기순이익 변화 = 기말재고 증가 600 - 기초재고 증가 300 = +300\n재작성 당기순이익 = 25,000 + 300 = 25,300","c":"상"},"관세사2018_35-51":{"w":"ㄱ. 대손추정 변경은 매 기말에 충당금을 다시 계산하므로 당기에만 영향을 준다.\nㄴ. 내용연수 변경은 당기와 남은 내용연수 동안의 감가상각비에 영향을 준다.\nㄷ. 경제적효익의 소비형태 변경도 당기와 미래의 감가상각비에 영향을 준다.\n정답은 ㄴ, ㄷ이다.","c":"상"},"관세사2018_35-65":{"w":"20×1년 순이익 효과를 차례로 반영한다.\n- 20×0년 기말재고 과소 8,000 → 20×1년 기초재고 과소로 매출원가 과소, 이익 과대 → -8,000\n- 20×1년 기말재고 과소 3,000 → 매출원가 과대, 이익 과소 → +3,000\n- 연구비 20,000을 자산으로 처리하고 상각 4,000 → 이익 과대 20,000 - 4,000 = 16,000 → -16,000\n수정 후 법인세비용차감전순이익 = 500,000 - 8,000 + 3,000 - 16,000 = 479,000","c":"상"},"관세사2020_37-69":{"w":"②가 옳지 않다. 과거에 발생하지 않았거나 중요하지 않았던 거래·사건에 새로운 회계정책을 적용하는 것은 회계정책의 변경이 아니다.\n⑤ 변경이 정책인지 추정인지 구분이 어려우면 추정의 변경으로 본다.","c":"상"},"관세사2024_41-41":{"w":"①이 옳다. 오류수정은 추가 정보가 알려질 때 변경될 수 있는 회계추정치 변경과 구별된다.\n②새 회계정책의 과거기간 적용에서 사후에 인지된 사실은 이용할 수 없다. ③적용할 기준이 없으면 경영진이 판단해 회계정책을 개발한다. ④⑤실질이 다른 거래나 과거에 없던 거래에 새 정책을 적용하는 것은 회계정책의 변경이 아니다.","c":"상"},"관세사2026_43-67":{"w":"회계정책변경은 소급적용하므로 당기 영향은 기초재고와 기말재고 변동분이다.\n기초재고 25,000 감소 → 매출원가 감소, 당기순이익 +25,000\n기말재고 20,000 감소 → 매출원가 증가, 당기순이익 -20,000\n순효과 +5,000이므로 변경 후 당기순이익 = 100,000 + 5,000 = 105,000","c":"상"},"관세사2017_34-61":{"w":"평균지출액 = 50,000,000×12/12 + 100,000,000×6/12 = 100,000,000\n특정차입금: 이자 20,000,000×9% = 1,800,000에서 투자수익 3,000,000×2%×4/12 = 20,000을 차감해 1,780,000을 자본화\n일반차입금 대상 평균지출액 = 100,000,000 - 20,000,000 = 80,000,000\n일반차입금 이자 = B 30,000,000×9% = 2,700,000 + C 60,000,000×10%×4/12 = 2,000,000 = 4,700,000, 평균차입금 50,000,000이므로 자본화이자율 9.4%\n80,000,000×9.4% = 7,520,000이 실제 이자 4,700,000을 넘으므로 4,700,000이 한도이다.\n자본화 차입원가 = 1,780,000 + 4,700,000 = 6,480,000","c":"상"},"관세사2017_34-62":{"w":"공정가치모형의 투자부동산 원가 = 매입가액 50,000 + 취득세 등 2,000 + 전문가 자문료 1,000 = 53,000\n20x1년 말 공정가치 52,000이므로 평가손실 1,000\n취득 담당부서 관리비 1,000은 취득원가가 아니라 당기비용\n20x1년 손익 = -1,000 - 1,000 = -2,000 (손실)","c":"상"},"관세사2018_35-59":{"w":"일반차입금 자본화액 400,000 = 일반차입금에 사용된 평균지출액 × 10%이므로 그 금액은 4,000,000이다. (실제 일반차입금 이자 500,000 이내)\n총지출 6,000,000 중 특정차입금으로 충당한 금액을 뺀 나머지가 일반차입금 지출이므로 특정차입금 = 6,000,000 - 4,000,000 = 2,000,000","c":"상"},"관세사2019_36-64":{"w":"⑤가 옳지 않다. 특정차입금의 일시적 운용에서 생긴 투자수익은 실제 발생한 차입원가에서 차감하여 자본화가능차입원가를 정한다. 가산하지 않는다.","c":"상"},"관세사2019_36-66":{"w":"공정가치모형을 적용하는 투자부동산은 감가상각을 하지 않는다. 감가상각비는 0이다.\n공정가치 변동이익 = 1,080,000 - 1,050,000 = 30,000","c":"상"},"관세사2020_37-54":{"w":"①이 옳지 않다. 투자부동산은 최초에 원가로 측정하며, 거래원가도 원가에 포함한다. 당기비용으로 처리하지 않는다.","c":"상"},"관세사2022_39-49":{"w":"정부보조금은 자산에서 차감한다. 장부금액 20,000-8,000 = 12,000, 연 감가상각비 12,000/5 = 2,400\n20×3년 말 장부금액 = 12,000 - 2,400×3 = 4,800\n처분손익 = 5,000 - 4,800 = +200 (이익)\n20×3년 순손익 = 감가상각비 -2,400 + 처분이익 200 = -2,200 (손실)","c":"상"},"관세사2022_39-53":{"w":"원가모형에서 공정가치모형으로의 변경은 회계정책 변경이지만, 20×5년 말 공정가치 42,000이 20×5년 말 장부금액이 된다. (20×6년 초 처분 시점의 장부금액 42,000)\n처분손익 = 36,000 - 42,000 = -6,000 (손실)","c":"중"},"관세사2023_40-67":{"w":"⑤가 옳지 않다. 투자부동산은 분류별로 선택하지 않고 모든 투자부동산에 하나의 모형(원가모형 또는 공정가치모형)을 적용한다.\n③개발 없이 처분하기로 결정해도 투자부동산으로 계속 분류하며 재고자산으로 대체하지 않는다.","c":"상"},"관세사2025_42-44":{"w":"특정차입금은 4/1에 300,000을 차입했고 4/1 지출 200,000과 7/1 지출 중 100,000에 쓰인다. 7/1 지출 중 나머지 200,000은 일반차입금에 해당한다.\n특정차입금 차입원가 = 300,000×5%×9/12 = 11,250, 투자수익 100,000×3%×3/12 = 750을 차감하면 10,500\n일반차입금 평균지출액 = 200,000×6/12 = 100,000, 자본화이자율 7%이므로 7,000 (실제 일반차입금 이자 49,000 이내)\n자본화할 차입원가 = 10,500 + 7,000 = 17,500","c":"상"},"관세사2026_43-50":{"w":"①이 옳다. 미래에 투자부동산으로 사용하기 위해 건설 또는 개발 중인 부동산도 투자부동산이다.\n②지배기업이나 다른 종속기업에 리스한 부동산은 연결재무제표에서 자가사용부동산이다. ③원가모형도 선택할 수 있다. ④개발 없이 처분하기로 해도 투자부동산으로 계속 분류한다. ⑤재고자산을 공정가치모형 투자부동산으로 대체할 때의 차액은 당기손익이다.","c":"상"},"관세사2017_34-63":{"w":"20x1년: 상각 100,000/5 = 20,000, 장부금액 80,000, 공정가치 88,000이므로 재평가잉여금 8,000 (기타포괄손익)\n20x2년: 상각 88,000/4 = 22,000, 장부금액 66,000, 공정가치 52,800이므로 재평가감소 13,200\n재평가감소는 먼저 재평가잉여금 8,000과 상계하고 나머지를 당기손익에 반영: 13,200 - 8,000 = 5,200","c":"상"},"관세사2017_34-70":{"w":"①이 옳지 않다. 새로운 지역이나 새로운 계층의 고객을 대상으로 사업을 수행하는 데서 발생하는 원가는 무형자산으로 인식하지 않고 비용 처리한다.","c":"상"},"관세사2018_35-48":{"w":"②가 옳지 않다. 최초에 비용으로 인식한 무형항목에 대한 지출은 그 이후에 무형자산의 원가로 인식할 수 없다.","c":"상"},"관세사2022_39-50":{"w":"①이 옳다. 자체 개발 웹 사이트는 무형자산의 일반 인식조건과 개발단계 6가지 요건을 모두 충족할 때 무형자산으로 인식한다.\n②판매촉진·광고용 웹 사이트 지출은 발생 시 비용이다. ③계획단계 지출은 비용이다. ⑤무형자산은 원칙적으로 원가모형을 적용한다.","c":"상"},"관세사2023_40-59":{"w":"⑤가 옳지 않다. 소비형태를 신뢰성 있게 결정할 수 없으면 정액법을 사용한다.\n④최초에 비용으로 인식한 지출은 이후 무형자산 원가로 인식할 수 없다는 설명은 맞다.","c":"상"},"관세사2025_42-48":{"w":"⑤가 옳다. 내용연수 종료 시점에 제3자가 구입하기로 약정한 경우(또는 활성시장이 있고 잔존가치가 거기서 결정되며 존재할 가능성이 높은 경우) 잔존가치를 영으로 보지 않는다.\n①비한정 내용연수를 유한으로 재평가하는 것은 손상 징후이다. ②연구결과 최종 선택 활동은 연구단계라 비용이다. ③사용 전 무형자산도 매년 손상검사를 한다. ④내부 창출 브랜드는 무형자산으로 인식하지 않는다.","c":"상"},"관세사2026_43-45":{"w":"③이 옳지 않다. 새로운 지역이나 새로운 계층의 고객을 대상으로 사업을 수행하는 데서 발생하는 원가는 무형자산의 취득원가에 포함하지 않는다.","c":"상"},"관세사2026_43-46":{"w":"소프트웨어 상각비 = 20,000/4 = 5,000\n특허권은 20×1년 말에 취득했으므로 20×2년부터 상각한다. 4,000/5 = 800\n20×2년 상각비 = 5,000 + 800 = 5,800","c":"상"},"관세사2017_34-64":{"w":"공정가치가 더 명백한 자동차(60,000)를 기준으로 하며 상업적 실질이 있다. 기계장치 공정가치 50,000 + 현금 10,000 = 60,000이다.\n기계장치 장부금액 = 100,000 - 55,000 = 45,000\n유형자산처분이익 = 50,000 - 45,000 = 5,000","c":"상"},"관세사2017_34-65":{"w":"연수합계법 상각대상 1,800,000(2,000,000-200,000), 합계 15\n20x1년(6개월) = 1,800,000×5/15×6/12 = 300,000\n20x2년 = 600,000×6/12 + 480,000×6/12 = 540,000\n20x3년 초 장부금액 = 2,000,000 - 300,000 - 540,000 = 1,160,000\n정액법 전환: 1,160,000/4 = 290,000, 20x3년 말 장부금액 870,000\n20x4년 초 처분 1,000,000 - 870,000 = 처분이익 130,000","c":"상"},"관세사2018_35-45":{"w":"⑤가 옳지 않다. 소비형태가 유의적으로 달라져 감가상각방법을 바꾸는 것은 회계정책 변경이 아니라 회계추정의 변경이다.","c":"상"},"관세사2018_35-55":{"w":"유형자산으로 처리하는 항목 합계:\n- 구건물 철거비용 1,500,000 (토지 원가)\n- 토지 취득세 600,000\n- 시운전비 2,000,000\n- 복구원가 현재가치 300,000\n- 특정차입금 자본화 차입원가 200,000\n- 중고자동차 수리비 300,000\n합계 4,900,000. 재산세는 비용이고, 사용하던 본사건물의 철거비용과 미상각잔액은 처분손실이다.","c":"상"},"관세사2018_35-58":{"w":"20×1년 상각 160,000/5 = 32,000, 말 장부금액 128,000, 회수가능액 84,000이므로 손상차손 44,000, 장부금액 84,000\n20×2년 상각 84,000/4 = 21,000, 말 장부금액 63,000\n손상이 없었다면 20×2년 말 장부금액 = 160,000 - 32,000×2 = 96,000 (환입 한도)\n회수가능액 100,000이 한도보다 크므로 환입액 = 96,000 - 63,000 = 33,000","c":"상"},"관세사2018_35-61":{"w":"20×1년: 상각 400,000, 장부금액 1,600,000, 공정가치 1,800,000이므로 재평가잉여금 200,000\n20×2년: 상각 1,800,000/4 = 450,000, 장부금액 1,350,000, 공정가치 1,050,000이므로 재평가감소 300,000\n재평가감소는 재평가잉여금 200,000을 먼저 상계하고 나머지 100,000을 당기손익으로 인식\n20×2년 당기순이익 감소 = 450,000 + 100,000 = 550,000","c":"상"},"관세사2018_35-63":{"w":"20×1~20×2년 상각 480,000/4 = 120,000씩, 20×3년 초 장부금액 240,000\n20×3년 초 내용연수 1년 연장: 남은 기간 2년 → 3년, 상각비 240,000/3 = 80,000\n20×3년 말 장부금액 160,000, 20×4년 9개월 상각 80,000×9/12 = 60,000 → 장부금액 100,000\n처분이익 = 130,000 - 100,000 = 30,000","c":"상"},"관세사2019_36-65":{"w":"①이 옳지 않다. 생물자산의 공정가치 측정에서 자금조달, 세금, 수확 후 복구 관련 현금흐름은 포함하지 않는다.","c":"상"},"관세사2019_36-67":{"w":"20×1년 말: 상각 200,000, 장부금액 800,000 → 공정가치 900,000, 재평가잉여금 100,000\n20×2년 말: 상각 225,000, 장부금액 675,000 → 공정가치 650,000, 재평가잉여금 25,000 감소(잔액 75,000). 회수가능액 510,000이므로 손상차손 140,000: 재평가잉여금 75,000 상계, 당기손익 65,000\n20×3년 말: 상각 510,000/3 = 170,000, 장부금액 340,000 → 공정가치 460,000, 재평가증가 120,000. 과거 당기손익으로 인식한 손상차손 65,000 한도에서 당기이익, 나머지 55,000은 재평가잉여금\n감가상각액을 제외한 당기이익 = 65,000","c":"중"},"관세사2019_36-69":{"w":"상각대상 750,000 - 30,000 = 720,000, 연수합계 15\n20×1년(9개월) = 720,000×5/15×9/12 = 180,000\n20×2년 = 240,000×3/12 + 192,000×9/12 = 60,000 + 144,000 = 204,000\n20×2년 말 감가상각누계액 = 180,000 + 204,000 = 384,000","c":"상"},"관세사2020_37-46":{"w":"기존 건물이 있는 토지를 취득해 건물을 즉시 철거하는 것은 토지를 사용하려는 목적이다. 건물분 취득가액을 따로 배분하지 않고 모두 토지 원가에 넣는다.\n토지 취득원가 = 7,500 + 철거비용 300 - 폐자재 처분수입 100 = 7,700","c":"상"},"관세사2020_37-56":{"w":"20×1년 상각 5,000/4 = 1,250, 말 장부금액 3,750\n회수가능액 = max(순공정가치 2,600, 사용가치 3,000) = 3,000, 손상차손 750, 장부금액 3,000\n20×2년 상각 3,000/3 = 1,000, 말 장부금액 2,000\n손상이 없었다면 20×2년 말 장부금액 = 5,000 - 1,250×2 = 2,500이 환입 한도\n환입액 = 2,500 - 2,000 = 500","c":"상"},"관세사2020_37-63":{"w":"⑤가 옳지 않다. 무형자산은 활성시장이 있어 공정가치를 알 수 있을 때만 재평가모형을 적용하고, 재평가 빈도는 공정가치 변동 정도에 따른다. 매 보고기간 말마다 재평가하는 것이 아니다.","c":"상"},"관세사2020_37-67":{"w":"정률법 상각률 45%를 적용한 결과가 선지 ④와 맞는다. (원문에 상각률이 빠져 있고 5년·잔존 10,000으로 구하면 약 45.6%이다.)\n20×1년(8개월) = 210,000×45%×8/12 = 63,000\n20×2년 = 1/1~4/30분 94,500×4/12 = 31,500 + 5/1~12/31분 (210,000-94,500)×45%×8/12 = 34,650 = 66,150\n20×2년 말 누계 = 63,000 + 66,150 = 129,150","c":"하"},"관세사2020_37-68":{"w":"20×2년 말 누계 감가상각 = (5,100-100)/5×2 = 2,000, 장부금액 3,100\n성능개선 1,500을 자본화하면 4,600\n20×3년 초 남은 내용연수 = 3 + 2 = 5년, 잔존가치 50\n20×3년 감가상각비 = (4,600 - 50)/5 = 910","c":"상"},"관세사2022_39-54":{"w":"20×1~20×2년 연 상각 (30,000-1,000)/5 = 5,800, 20×2년 말 장부금액 18,400\n회수가능액 = max(9,000, 16,000) = 16,000, 손상차손 2,400, 장부금액 16,000\n20×3년 상각 (16,000-1,000)/3 = 5,000, 말 장부금액 11,000\n손상이 없었다면 20×3년 말 장부금액 = 30,000 - 5,800×3 = 12,600이 환입 한도\n회수가능액 13,000이 한도보다 크므로 환입액 = 12,600 - 11,000 = 1,600","c":"상"},"관세사2022_39-55":{"w":"(가) 상업적 실질이 있고 제공한 자산(A)의 공정가치를 알 수 없으면 취득한 자산(B)의 공정가치 8,000을 원가로 한다.\n(나) 상업적 실질이 없으면 제공한 자산의 장부금액으로 측정한다. A 장부금액 9,000-3,500 = 5,500에 현금 1,500을 더한 7,000이다.","c":"하"},"관세사2023_40-68":{"w":"ㄱ. 자가사용 부동산은 현금흐름이 다른 자산에도 귀속되므로 유형자산이다.\nㄴ. 상업적 실질이 없는 교환은 제공한 자산의 장부금액으로 인식한다.\nㄷ. 복구원가는 충당부채 인식요건을 충족할 때에만 원가에 가산한다.\nㄹ. 감가상각자산의 정부보조금은 감가상각 기간과 비율에 따라 당기손익으로 인식한다.\n정답은 ㄱ, ㄹ이다.","c":"상"},"관세사2023_40-69":{"w":"연수합계법(ㄴ): 상각대상 900,000, 합 10\n20×1년(6개월) = 900,000×4/10×6/12 = 180,000\n20×2년 = 360,000×6/12 + 270,000×6/12 = 180,000 + 135,000 = 315,000\n정률법(ㄱ): 원문에 상각률이 빠져 있어 선지 ③에서 역산하면 상각률 50%이다.\n20×2년 = 1,000,000×50%×6/12 + 500,000×50%×6/12 = 250,000 + 125,000 = 375,000","c":"하"},"관세사2023_40-70":{"w":"20×1년 상각 100,000, 장부금액 400,000, 회수가능액 320,000이므로 손상차손 80,000, 장부금액 320,000\n20×2년 상각 320,000/4 = 80,000, 장부금액 240,000\n손상이 없었다면 20×2년 말 장부금액 = 500,000 - 200,000 = 300,000이 환입 한도\n회수가능액 310,000이 한도를 넘으므로 환입액 = 300,000 - 240,000 = 60,000","c":"상"},"관세사2024_41-56":{"w":"20×1년: 상각 10,000/10 = 1,000, 장부금액 9,000, 공정가치 12,600이므로 재평가잉여금 3,600\n20×2년: 상각 12,600/9 = 1,400 (당기비용), 장부금액 11,200, 공정가치 6,000이므로 재평가감소 5,200\n재평가감소는 재평가잉여금 3,600을 먼저 상계하고 나머지 1,600을 당기손익으로 인식\n당기순이익 영향 = -1,400 - 1,600 = -3,000","c":"상"},"관세사2024_41-63":{"w":"20×3년 초 장부금액 = 10,000 - 2,000×2 = 6,000, 자본적 지출 3,000을 더하면 9,000\n남은 내용연수 = 3년 + 2년 연장 = 5년\n연수합계법 첫 해 상각률 5/15이므로 20×3년 감가상각비 = 9,000×5/15 = 3,000","c":"상"},"관세사2025_42-49":{"w":"20×1년: 상각 20,000, 장부금액 80,000, 공정가치 70,000이므로 재평가손실 10,000 (당기손익)\n20×2년 초 후속원가 10,000을 더하면 장부금액 80,000, 남은 4년 상각 80,000/4 = 20,000\n20×2년 말 장부금액 60,000, 공정가치 68,000이므로 재평가증가 8,000: 앞서 당기손익으로 인식한 손실 10,000 한도 내에서 당기이익\n당기순이익 영향 = -20,000 + 8,000 = -12,000","c":"상"},"관세사2025_42-65":{"w":"20×3년 초 장부금액 = 250,000 - 50,000×2 = 150,000, 자본적 지출 20,000을 더하면 170,000\n남은 내용연수 = 3 + 1 = 4년, 잔존가치 10,000\n20×3년 감가상각비 = (170,000 - 10,000)/4 = 40,000","c":"상"},"관세사2026_43-47":{"w":"20×1~20×2년 상각 14,000/5 = 2,800씩, 20×2년 말 장부금액 8,400\n회수가능액 = max(사용가치 7,800, 순공정가치 4,800) = 7,800, 손상차손 600, 장부금액 7,800\n20×3년 상각 7,800/3 = 2,600, 말 장부금액 5,200\n손상이 없었다면 20×3년 말 장부금액 = 14,000 - 2,800×3 = 5,600이 환입 한도\n환입액 = 5,600 - 5,200 = 400","c":"상"},"관세사2026_43-69":{"w":"ㄱ. 생물자산은 원칙적으로 공정가치(순공정가치)로 측정한다. 원가모형 선택 대상이 아니다.\nㄴ. 수확물은 수확시점에 순공정가치로 측정한다.\nㄷ. 순공정가치 변동에서 생기는 평가손익은 당기손익이다.\nㄹ. 조건이 없는 정부보조금은 수취할 수 있게 되는 시점에 당기손익으로 인식한다.\n정답은 ㄴ, ㄹ이다.","c":"상"},"관세사2017_34-66":{"w":"퇴직급여 = 당기근무원가 + 순확정급여부채의 순이자\n순확정급여부채 기초 = 4,300,000 - 3,500,000 = 800,000, 순이자 = 800,000×10% = 80,000\n퇴직급여 = 760,000 + 80,000 = 840,000","c":"상"},"관세사2018_35-70":{"w":"확정급여채무 기대액 = 기초 700,000 + 당기근무원가 150,000 + 이자원가 70,000 - 퇴직급여 지급 90,000 = 830,000\n기말 확정급여채무 850,000이 기대보다 20,000 많으므로 보험수리적손실 20,000(기타포괄손실)","c":"상"},"관세사2022_39-62":{"w":"당기분 7일을 먼저 소진하므로 7일 이내를 쓰는 160명은 이월분을 사용하지 않아 추가 부담이 없다.\n40명은 평균 11일을 쓰므로 당기분 7일 외에 이월분 4일을 쓴다.\n20×1년 말 부채 = 40명×4일×15 = 2,400","c":"상"},"관세사2023_40-52":{"w":"확정급여채무 기대액 = 180 + 근무원가 40 + 이자원가 180×10% = 18 - 지급 50 = 188\n기말 확정급여채무 160이 기대보다 28 적으므로 보험수리적이익 28","c":"상"},"관세사2024_41-51":{"w":"기초 순확정급여부채 = 1,200 - 1,000 = 200\n순이자 = 200×5% = 10, 당기근무원가 200, 사외적립자산 출연 -300\n기말 순확정급여부채 = 200 + 10 + 200 - 300 = 110","c":"상"},"관세사2024_41-62":{"w":"④가 옳지 않다. 확정기여제도는 출연금액이 곧 비용이고 채무를 따로 측정하지 않으므로 보험수리적가정이 필요하지 않다. 보험수리적가정이 필요한 것은 확정급여제도이다.","c":"상"},"관세사2025_42-67":{"w":"순확정급여부채 기초가 0이므로 순이자는 0이다.\n확정급여채무 기말 120,000 = 기초 X + 당기근무원가 40,000 + 이자 → 사외적립자산 기대액 = 기초 + 이자 + 출연 50,000이고 기초와 이자는 채무와 같은 크기 80,000이다.\n기대 사외적립자산 = 80,000 + 50,000 = 130,000\n기말 순확정급여부채가 0이므로 사외적립자산 공정가치는 120,000\n재측정요소 = 120,000 - 130,000 = -10,000 (기타포괄이익 10,000 감소)","c":"중"},"관세사2026_43-57":{"w":"사외적립자산 기초 20,000\n실제 투자수익 20,000×10% = 2,000 증가\n기여 +10,000, 퇴직급여 지급 -5,000\n기말 = 20,000 + 2,000 + 10,000 - 5,000 = 27,000","c":"상"},"관세사2017_34-67":{"w":"식별가능한 순자산의 공정가치 = 순자산 장부금액 200,000 + 유형자산 평가차이 70,000 + 식별된 무형자산(연구개발프로젝트) 50,000 = 320,000\n영업권 = 이전대가 400,000 - 320,000 = 80,000","c":"상"},"관세사2018_35-69":{"w":"⑤가 옳지 않다. 3,000,000에 인수하면 영업권 = 3,000,000 - 순자산 공정가치 1,400,000 = 1,600,000이다.\n①자산총액 = 현금 200,000 + 재고 200,000 + 유형자산 1,000,000 + 특허권 100,000 + 영업권 1,600,000 = 3,100,000\n③400,000에 인수하면 염가매수차익 1,000,000을 당기이익으로 인식하고, 자산총액은 1,500,000이다.","c":"상"},"관세사2020_37-43":{"w":"⑤가 옳지 않다. 비지배지분의 조정금액과 지급·수취한 대가의 공정가치 차이는 자본으로 직접 인식하고 지배기업의 소유주에게 귀속시킨다. 비지배지분 소유주에게 귀속시키는 것이 아니다.","c":"상"},"관세사2022_39-51":{"w":"식별가능한 순자산 공정가치 31,000 > 이전대가 30,000이므로 염가매수차익이 생긴다.\n염가매수차익 = 31,000 - 30,000 = 1,000","c":"상"},"관세사2023_40-57":{"w":"신기술 개발비는 무형자산 정의를 충족하므로 공정가치 20,000을 인식한다.\n식별가능 순자산 공정가치 = 170,000 + 20,000 = 190,000\n영업권 = 이전대가 200,000 - 190,000 = 10,000","c":"상"},"관세사2024_41-64":{"w":"⑤가 옳지 않다. 종속기업·공동기업·관계기업에서 받는 배당금은 배당을 받을 권리가 확정되는 시점에 별도재무제표에 인식한다. 배당을 수취한 시점이 아니다.","c":"상"},"관세사2017_34-68":{"w":"발행시점 부채 = 10,000×2.5771 + 200,000×0.7938 = 25,771 + 158,760 = 184,531 (원문에 단일금액 현가가 빠져 있어 0.7938을 사용)\n20x1년 말 장부금액 = 184,531 + 14,762 - 10,000 = 189,293\n20x2년 1월 1일 액면 80,000(40%)이 전환되어 남은 60%의 장부금액은 189,293×60% = 113,576\n20x2년 이자비용 = 113,576×8% = 9,086","c":"중"},"관세사2019_36-57":{"w":"20×3년 1월 1일 부채 장부금액은 (1,000,000/1.05²) 약 952,339 이고 60%가 전환되므로 부채 장부금액 571,404가 보통주 발행에 대응한다. (원문에 현가계수가 빠져 있어 3년 5% 현가계수 0.8638 사용)\n전환권대가 중 전환분은 이미 자본에 있어 자본 내부 대체이다.\n전환으로 늘어나는 자본 = 전환된 부채의 장부금액 = 571,404","c":"중"},"관세사2023_40-63":{"w":"부채 발행금액 = 100,000×0.8638 = 86,380, 전환권대가 = 100,000 - 86,380 = 13,620\n20×1년 말 부채 장부금액 = 86,380×1.05 = 90,699, 60% 전환분 = 54,419\n전환권대가 중 전환분 = 13,620×60% = 8,172\n액면 60,000에 해당하는 주식 12주(60,000/5,000), 자본금 12×500 = 6,000\n주식발행초과금 = 54,419 + 8,172 - 6,000 = 56,591","c":"상"},"관세사2024_41-52":{"w":"발행 시 부채 = 5,000×3.1700 + 100,000×0.6830 = 15,850 + 68,300 = 84,150\n20×1년 이자비용 = 84,150×10% = 8,415\n20×1년 말 장부금액 = 84,150 + 8,415 - 5,000 = 87,565","c":"상"},"관세사2025_42-54":{"w":"신주인수권이 행사되면 행사가액 현금이 납입되고 사채는 그대로 남는다. 신주인수권대가는 이미 자본이다.\n행사된 신주인수권은 액면의 40%에 해당하므로 납입 현금 = 1,000,000×40% = 400,000\n행사시점 자본총액 증가 = 400,000","c":"상"},"관세사2026_43-55":{"w":"전환사채의 부채 요소는 만기 상환할증을 반영한 현금흐름의 현재가치이다.\n표시이자 100,000×6% = 6,000 → 6,000×2.4868 = 14,921\n만기 상환액 106,493 → 106,493×0.7513 = 80,008\n부채 = 14,921 + 80,008 = 94,929","c":"상"},"관세사2017_34-69":{"w":"②가 옳지 않다. 의무에는 이행 대상인 상대방이 있어야 하나, 상대방이 누구인지 알 필요는 없고 일반대중에 대한 의무도 충당부채로 인식할 수 있다.","c":"상"},"관세사2018_35-49":{"w":"③이 옳지 않다. 우발부채로 처리했던 항목이라도 이후에 자원 유출 가능성이 높아지고 금액을 신뢰성 있게 추정할 수 있으면 충당부채로 인식한다.","c":"상"},"관세사2018_35-66":{"w":"제품보증비용은 판매한 연도에 매출액의 5%로 인식한다.\n20×1년 품질보증비용 = 300,000×5% = 15,000\n실제 지출 6,000은 충당부채를 줄이는 것이며 비용이 아니다.","c":"상"},"관세사2019_36-68":{"w":"20×1년 초 복구충당부채 = 200,000×0.6806 = 136,120이고 취득원가는 1,136,120이다.\n20×1년 감가상각비 = 1,136,120/5 = 227,224 (③이 옳다).\n①④: 충당부채는 136,120, 20×1년 이자비용은 136,120×8% = 10,890이다. ②취득원가는 1,136,120이다. ⑤실제 복구비용 230,000이 장부 200,000보다 커서 복구공사손실 30,000이 생긴다.","c":"상"},"관세사2020_37-62":{"w":"충당부채는 의무 이행에 필요한 지출 500,000 전액이다. 제삼자의 변제 30%(150,000)는 거의 확실하므로 별도의 자산(미수금)으로 인식하고 충당부채와 상계하지 않는다.\n포괄손익계산서에서는 충당부채전입 비용 500,000과 변제수익 150,000을 상계해 표시할 수 있다.\n당기순이익 영향 = -500,000 + 150,000 = -350,000 (350,000 감소)","c":"상"},"관세사2022_39-58":{"w":"⑤가 옳지 않다. 예상되는 자산 처분이익은 충당부채를 측정할 때 고려하지 않는다.\n③은 제삼자와 연대하여 부담하는 의무 중 제삼자가 이행할 것으로 예상되는 부분을 우발부채로 처리한다는 설명으로 맞다.","c":"상"},"관세사2024_41-57":{"w":"복구원가 현재가치 = 200,000×PV(4년, 10%) = 200,000×0.6830 = 136,600 (원문에 현가계수가 빠져 있어 0.6830 사용)\n해상구조물 원가 = 2,000,000 + 136,600 = 2,136,600\n감가상각비 = (2,136,600 - 200,000)/4 = 484,150\n복구충당부채 이자비용 = 136,600×10% = 13,660\n20×1년 총비용 = 484,150 + 13,660 = 497,810","c":"중"},"관세사2025_42-51":{"w":"복구충당부채 = 500,000×PV(10년, 5%) = 500,000×0.6139 = 306,950 (원문에 현가계수가 빠져 있어 0.6139 사용)\n시설물 원가 = 1,000,000 + 306,950 = 1,306,950, 연 감가상각비 130,695\n복구충당부채 20×1년 이자비용 15,348 → 말 잔액 322,298\n20×2년 이자비용 = 322,298×5% = 16,115 (반올림 오차로 16,114)\n20×2년 비용 = 130,695 + 16,114 = 146,809","c":"중"},"관세사2026_43-56":{"w":"④가 옳지 않다. 제삼자와 연대하여 의무를 지는 경우, 이행할 전체 의무 중 제삼자가 이행할 것으로 예상되는 부분은 우발부채로 처리하며 충당부채로 인식하지 않는다.","c":"상"},"관세사2017_34-71":{"w":"매출원가 = 302,500×(1-20%) = 242,000\n제품: 90,000 + 당기제품제조원가 - 120,000 = 242,000 → 당기제품제조원가 272,000\n재공품: 100,000 + 당기총제조원가 - 40,000 = 272,000 → 당기총제조원가 212,000\n직접재료원가 = 212,000 - 직접노무원가 70,000 - 제조간접원가 52,000 = 90,000\n재료: 20,000 + 매입액 - 40,000 = 90,000 → 재료매입액 110,000","c":"상"},"관세사2018_35-71":{"w":"당기총제조원가 = 당기제품제조원가 1,400,000 + 기말재공품 200,000 - 기초재공품 100,000 = 1,500,000\n당기총제조원가는 기본원가와 가공원가를 합친 값에서 겹치는 직접노무원가를 한 번 뺀 값이다.\n1,500,000 = 1,200,000 + 1,100,000 - 직접노무원가 → 직접노무원가 800,000","c":"상"},"관세사2018_35-72":{"w":"판매비 성격인 화재보험료를 제조간접원가에 넣으면 제품원가가 늘어난다. 이 중 판매된 800개분만 매출원가가 되어 매출총이익이 줄고, 재고 200개분은 재고자산으로 남아 비용이 이연된다.\n판매비로 처리했을 때는 전액이 영업이익에서 차감되므로 영업이익은 오히려 증가한다.\n매출총이익 감소, 영업이익 증가","c":"상"},"관세사2019_36-74":{"w":"제조간접원가 = 전환원가 2,250,000 - 직접노무원가 750,000 = 1,500,000\n당기총제조원가 = 직접재료 830,000 + 전환원가 2,250,000 = 3,080,000\n당기제품제조원가 = 170,000 + 3,080,000 - 320,000 = 2,930,000\n매출원가 = 130,000 + 2,930,000 - 110,000 = 2,950,000\n매출총이익 = 3,835,000 - 2,950,000 = 885,000","c":"상"},"관세사2020_37-71":{"w":"매출원가 = 400,000×(1-25%) = 300,000\n제품: 90,000 + 당기제품제조원가 - 100,000 = 300,000 → 당기제품제조원가 310,000\n재공품: 50,000 + 당기총제조원가 - 40,000 = 310,000 → 당기총제조원가 300,000\n직접재료원가 사용액 = 300,000 - 전환원가 130,000 = 170,000\n재료: 20,000 + 180,000 - 월말재고 = 170,000 → 월말 직접재료 30,000","c":"상"},"관세사2023_40-73":{"w":"직접재료 사용액 = 100,000 + 200,000 - 120,000 = 180,000\n당기제품제조원가: 10,000 + x - 20,000 = 560,000 → 570,000\n당기총제조원가: 210,000 + y - 240,000 = 570,000 → 600,000\n기본원가:전환원가 = 1:2이고 기본원가 = 180,000 + 직접노무원가(DL), 전환원가 = DL + 제조간접원가이므로 총제조원가 600,000 = 기본원가 + 전환원가 - DL\n기본원가 = b라 하면 3b - DL = 600,000, b = 180,000 + DL → DL = 30,000, b = 210,000, 전환원가 420,000\n제조간접원가 = 420,000 - 30,000 = 390,000","c":"상"},"관세사2025_42-75":{"w":"⑤가 옳지 않다. 제조간접원가 = 간접재료원가 3,000 + 간접노무원가 2,000 + 공장건물감가상각비 10,000 + 기타제조간접원가 1,000 = 16,000이다.\n① 직접노무원가 = 전환원가 40,000 - 16,000 = 24,000\n④ 당기총제조원가 = 기본원가 75,000 + 제조간접원가 16,000 = 91,000\n③ 판매관리비 = 본사임원급여 8,000 + 광고비 12,000 + 영업사원급여 6,000 = 26,000","c":"상"},"관세사2026_43-74":{"w":"④가 옳다. 당기총제조원가는 당기에 투입한 직접재료원가, 직접노무원가, 제조간접원가의 합이며 기초재공품은 포함하지 않는다.\n①총변동원가는 조업도에 비례해 늘어난다. ②수익을 얻기 위해 소멸한 원가는 비용이다. ③그 설명은 원가대상이다. ⑤변동원가와 고정원가는 조업도에 따른 분류이다.","c":"상"},"관세사2026_43-75":{"w":"직접재료원가가 기본원가의 60%이면 직접노무원가 50,000이 40%이므로 기본원가는 125,000이고 직접재료원가는 75,000이다.\n당기총제조원가 = 75,000 + 50,000 + 45,000 = 170,000\n당기제품제조원가 = 20,000 + 170,000 - 25,000 = 165,000","c":"상"},"관세사2017_34-72":{"w":"분개는 제조간접원가 배부차이 계정의 차변 잔액 60,000(과소배부)을 매출원가로 정리하는 것이다.\nㄷ. 배부차이가 차변 잔액이었으므로 제조간접원가가 60,000 과소배부되었다.\nㄹ. 매출원가에 60,000을 가산한다.\nㅁ. 매출원가가 늘어 매출총이익이 60,000 감소한다.\nㄱ(실제배부시 분개), ㄴ(표준원가 원가차이 조정)은 해당하지 않는다. 정답은 ㄷ, ㄹ, ㅁ이다.","c":"중"},"관세사2018_35-73":{"w":"예정배부율 = 192,400/3,700 = 52원/시간\n3월 배부액 = 450×52 = 23,400\n배부차이 1,300이 과대배부이므로 실제발생액이 배부액보다 1,300 적다.\n실제발생액 = 23,400 - 1,300 = 22,100","c":"상"},"관세사2019_36-71":{"w":"직접배부법은 보조부문 상호 용역수수를 무시하고 제조부문 사이의 사용량 비율로만 배부한다.\n수선부문: 절단 60/(60+20) = 75% → 250,000×75% = 187,500\n동력부문: 절단 350/(350+450) = 43.75% → 170,000×43.75% = 74,375\n절단부문 배부액 = 187,500 + 74,375 = 261,875","c":"상"},"관세사2019_36-75":{"w":"예정배부율 = 1,280,000/4,000시간 = 320\n배부액: 단거리 495×320 = 158,400, 중거리 1,485×320 = 475,200, 장거리 1,980×320 = 633,600, 합계 1,267,200\n실제 1,170,000과의 차이 97,200은 과대배부\n원가요소별 비례배분법은 제조간접원가 배부액 비율로 나눈다. 단거리 비율 158,400/1,267,200 = 1/8이므로 단거리(매출원가)에서 97,200×1/8 = 12,150 감소\n매출원가 = (240,000 + 150,000 + 158,400) - 12,150 = 536,250","c":"상"},"관세사2020_37-73":{"w":"상호배부법: 수선 S, 동력 D라 하면\nS = 260,000 + 0.25D, D = 100,000 + 0.20S\nS = 260,000 + 0.25×(100,000 + 0.2S) = 285,000 + 0.05S → S = 300,000, D = 160,000\n조립부문 배부액 = 수선 300,000×35% + 동력 160,000×20% = 105,000 + 32,000 = 137,000","c":"상"},"관세사2020_37-75":{"w":"예정배부율 = 2,000,000/5,000시간 = 400\n화물선 배부액 700×400 = 280,000, 매출원가(조정 전) = 240,000 + 280,000 + 280,000 = 800,000\n총 배부액 = (700+1,200+1,600)×400 = 1,400,000, 실제 1,500,000이므로 100,000 과소배부\n매출원가에서 전액 조정하므로 매출원가 = 800,000 + 100,000 = 900,000","c":"상"},"관세사2022_39-71":{"w":"총원가비례배분법은 배부차이를 기말재공품, 기말제품, 매출원가의 비율로 나눈다. 원재료는 배부 대상이 아니다.\n세 계정 합계 = 90,000 + 230,000 + 680,000 = 1,000,000\n과소배부 150,000의 배분: 재공품 13,500, 제품 34,500, 매출원가 102,000을 각각 가산\n조정 후 기말재고자산 = 원재료 250,000 + 재공품 103,500 + 제품 264,500 = 618,000","c":"상"},"관세사2023_40-72":{"w":"단계배부법으로 전력부문부터 배부한다.\n전력 200,000: 냉방 60% = 120,000, 사출 30% = 60,000, 열처리 10% = 20,000\n냉방부문 원가 = 330,000 + 120,000 = 450,000 (전력부문에는 배부하지 않으므로 사출:열처리 = 40:50)\n냉방 450,000 중 열처리 50/90 = 250,000\n열처리부문 배부액 = 20,000 + 250,000 = 270,000","c":"상"},"관세사2025_42-73":{"w":"이중배부율법은 고정원가는 최대사용가능량, 변동원가는 실제사용량 기준으로 나눈다.\n고정원가 180,000 중 성형 300/800 = 67,500\n변동원가 120,000 중 성형 200/500 = 48,000\n성형부문 배부액 = 67,500 + 48,000 = 115,500","c":"상"},"관세사2026_43-72":{"w":"예정배부율 = 150,000/10,000시간 = 15\n배부차이 8,800 불리(과소배부)이므로 배부액 = 실제 160,000 - 8,800 = 151,200\n실제 직접노무시간 = 151,200/15 = 10,080시간\n단위당 = 10,080/900 = 11.2시간","c":"상"},"관세사2017_34-73":{"w":"단위당 공헌이익 = 200 - 30 - 20 - 40 - 10 = 100\n세후목표이익 30,000을 세전으로 바꾸면 30,000/(1-20%) = 37,500 (원문에 세율이 빠져 있어 선지 ④에서 20%로 역산)\n판매수량 = (고정원가 200,000 + 37,500)/100 = 2,375단위","c":"중"},"관세사2018_35-77":{"w":"⑤가 옳다. 공헌이익 20,000이 판매량에 비례하므로 판매량 10% 증가 시 공헌이익 2,000 증가, 고정원가가 같으므로 영업이익도 2,000 증가한다.\n① 공헌이익률 20,000/50,000 = 40%\n② 손익분기점 매출 15,000/40% = 37,500이므로 안전한계율 25%\n③ 손익분기점 매출액은 37,500\n④ 영업레버리지도 20,000/5,000 = 4","c":"상"},"관세사2018_35-79":{"w":"전체 공헌이익률 = (4,500,000 - 2,475,000)/4,500,000 = 45%\n전체 손익분기점 매출액 = 810,000/45% = 1,800,000\n매출배합이 일정하므로 제품A 비중 900,000/4,500,000 = 20%\n제품A 손익분기점 매출액 = 1,800,000×20% = 360,000","c":"상"},"관세사2019_36-77":{"w":"20×1년 판매량 = 80,000/250 = 320단위\n20×2년 단위당 변동원가 130, 단위당 공헌이익 120, 고정원가 20,000, 목표 영업이익 22,000\n판매량 = (20,000 + 22,000)/120 = 350단위\n증가분 = 350 - 320 = 30단위","c":"상"},"관세사2020_37-78":{"w":"영업레버리지도 = 공헌이익/영업이익이다. (주)관세 48,000/20,000 = 2.4, (주)한국 36,000/20,000 = 1.8\n④가 옳다. 영업레버리지도는 손익분기점 부근에서 가장 높고, 판매량이 늘수록 낮아진다.\n①영업이익 증감률이 판매량 증감률보다 크다. ②(주)관세의 영업이익 증감률이 더 높다. ③차이 원인은 변동원가율과 고정원가의 구조이다. ⑤침체 시 위험은 (주)관세가 더 크다.","c":"상"},"관세사2022_39-78":{"w":"공헌이익률 = 1 - 36% = 64%, 공헌이익 = 5,000×64% = 3,200, 고정원가 = 3,200 - 2,000 = 1,200\n손익분기점 매출액 = 1,200/0.64 = 1,875\n(가) 안전한계율 = (5,000 - 1,875)/5,000 = 62.5%\n(나) 세후 2,112 → 세전 2,112/(1-20%) = 2,640, 매출액 = (1,200 + 2,640)/0.64 = 6,000","c":"상"},"관세사2023_40-76":{"w":"⑤가 옳지 않다. 실제 판매량 2,700단위는 예산 3,000단위의 90%이므로 공헌이익이 153,000, 세전영업이익이 51,000이고 세후영업이익은 35,700이다.\n① 매출액 X 200,000, Y 300,000이므로 배합 40%:60%\n② 가중평균 공헌이익률 (50,000+120,000)/500,000 = 34%, 손익분기점 매출 102,000/0.34 = 300,000\n③ 세전목표이익 85,000이면 매출 (102,000+85,000)/0.34 = 550,000, Y의 60% = 330,000\n④ 판매량 10% 증가 시 영업이익 68,000 → 85,000 (25% 증가)","c":"상"},"관세사2023_40-79":{"w":"고저점법으로 제조간접원가 = 9×생산량 + 5,000이므로 1,000단위 14,000, 2,000단위 23,000\n외주가공비(변동) 2,000단위 10,000이면 단위당 5, 1,000단위 5,000. 감가상각비(고정) 2,000\n기타제조원가 = 1,000단위 14,000-5,000-2,000 = 7,000, 2,000단위 23,000-10,000-2,000 = 11,000\n기타제조원가의 변동원가율 (11,000-7,000)/1,000 = 4, 고정 3,000\n3,000단위: 4×3,000 + 3,000 = 15,000","c":"상"},"관세사2024_41-78":{"w":"현금흐름분기점은 영업현금흐름이 0이 되는 판매량이다. 감가상각비 10,000은 현금유출이 없다.\n단위당 공헌이익 = 500 - 200 = 300\n세후 영업현금흐름 = (300Q - 50,000)×(1-20%) + 감가상각비 10,000 = 0\n300Q - 50,000 = -12,500 → Q = 125단위","c":"상"},"관세사2025_42-76":{"w":"①이 옳지 않다. 판매량 1,200,000/2,000 = 600단위, 단위당 변동원가 500+400+350+250 = 1,500, 단위당 공헌이익 500, 고정원가 240,000\n손익분기점 판매량 = 240,000/500 = 480단위, 안전한계율 = (600-480)/600 = 20%\n세전영업이익 = 300,000 - 240,000 = 60,000, 영업레버리지도 300,000/60,000 = 5\n세후 60,000 → 세전 100,000, 매출액 = (240,000+100,000)/25% = 1,360,000","c":"상"},"관세사2017_34-74":{"w":"경제적 부가가치 = 세후영업이익 - 투하자본×가중평균자본비용\n법인세율을 30%로 놓으면 (원문에 세율이 빠져 있어 선지 ⑤에서 역산) 세후영업이익 = 4,000×0.7 = 2,800\n투하자본 = 자산 20,000 - 유동부채 6,000 = 14,000\n가중평균자본비용 = (14,000×10%×0.7 + 14,000×14%)/28,000 = 10.5%\nEVA = 2,800 - 14,000×10.5% = 1,330","c":"중"},"관세사2018_35-75":{"w":"④가 옳지 않다. 종업원 만족도와 이직률은 학습과 성장 관점의 지표이다. 내부 프로세스 관점은 업무가 효율적으로 수행되는 정도를 측정한다.","c":"상"},"관세사2019_36-80":{"w":"부문A: 영업자산회전율 5이므로 매출 = 600,000×5 = 3,000,000, 영업이익 = 600,000×20% = 120,000, 이익률 4%, RI = 120,000 - 600,000×15% = 30,000\n부문B: 영업자산 = 162,000/18% = 900,000, 매출 = 900,000×4.5 = 4,050,000, 이익률 4%, RI = 162,000 - 900,000×15% = 27,000\n②가 옳지 않다. 부문B 매출액은 4,050,000이다.","c":"상"},"관세사2020_37-72":{"w":"⑤가 옳다. 경제적부가가치는 타인자본비용과 자기자본비용을 모두 반영한 가중평균자본비용을 쓴다.\n①투자수익률은 준최적화 문제를 일으킬 수 있다. ②규모가 다른 투자중심점 비교에는 잔여이익이 아니라 투자수익률이 쓰인다. ③두 지표에서 채택되는 투자안이 다를 수 있다. ④균형성과표의 관점은 조직에 따라 달라질 수 있다.","c":"상"},"관세사2022_39-77":{"w":"잔여이익 = 영업이익 - 평균영업자산×최저필수수익률: A 135, B 126, C 124, D 130\n투자수익률: A 28%, B 25%, C 27.5%, D 26.25%\n⑤가 옳지 않다. 잔여이익은 A가 가장 크지만, 투자수익률이 가장 큰 것은 C가 아니라 A(28%)이다.","c":"상"},"관세사2024_41-80":{"w":"영업이익 = 투자수익률 12%×10,000 = 1,200\n잔여이익 200 = 1,200 - 10,000×최저요구수익률 → 최저요구수익률 = 10%","c":"상"},"관세사2025_42-77":{"w":"경제적 부가가치 = 세후영업이익 - 투하자본×가중평균자본비용\n세후영업이익 = 135,000×(1-30%) = 94,500\n투하자본 = 총자산 600,000 - 이자 발생하지 않는 유동부채 180,000 = 420,000\nEVA = 94,500 - 420,000×15% = 31,500","c":"상"},"관세사2026_43-80":{"w":"사업부 X는 최대생산능력이라 사내대체 시 외부 판매를 포기해야 한다.\n최소대체가격 = 대체로 증가하는 지출 + 포기하는 공헌이익 = 외부 판매가 1,000 - 대체 시 절감되는 변동판매관리비 200 = 800\n최대대체가격 = 사업부 Y의 외부구매가 900\n800 ≤ TP ≤ 900","c":"상"},"관세사2017_34-75":{"w":"완성품 수량 = 5,000 + 20,000 - 7,500 = 17,500단위\n평균법: 환산량 = 17,500 + 7,500×20% = 19,000, 원가 = 1,050,000 + 17,000,000 = 18,050,000, 단위원가 950, 기말재공품 가공원가 = 1,500×950 = 1,425,000\n선입선출법: 환산량 = (17,500 - 5,000×40%) + 1,500 = 17,000, 단위원가 17,000,000/17,000 = 1,000, 기말재공품 가공원가 = 1,500×1,000 = 1,500,000","c":"상"},"관세사2018_35-76":{"w":"검사는 가공원가 60% 시점이다. 기초재공품(70%)과 기말재공품(80%)은 모두 검사 시점을 지났으므로, 기초재공품은 전기에 이미 검사를 통과했다.\n당기에 검사를 통과한 정상품 = 완성품 1,360 + 기말재공품 300 - 기초재공품 260 = 1,400단위\n정상공손수량 = 1,400×5% = 70단위","c":"중"},"관세사2020_37-77":{"w":"평균법: 직접재료 = 2,400 + 600 = 3,000(①), 전환원가 = 2,400 + 600×50% = 2,700(③)\n선입선출법: 직접재료 = 3,000 - 기초 1,000 = 2,000(②), 전환원가 = 2,700 - 1,000×60% = 2,100\n④ 선입선출법 전환원가 환산량은 2,200이 아니라 2,100이므로 옳지 않다.\n⑤ 차이는 기초재공품 때문에 생긴다.","c":"상"},"관세사2022_39-72":{"w":"전체 원가 = 160,000 + 210,000 + 340,000 + 460,000 = 1,170,000, 완성품 원가 = 1,000×900 = 900,000, 평균법 기말재공품 270,000\n평균법 환산량 = 1,170,000/900 = 1,300 → 기말재공품 환산량 300(완성도 60%)\n선입선출법 환산량은 평균법보다 300 적은 1,000(기초재공품 환산량 300 = 400×75%)\n선입선출법 단위원가 = 당기발생 (340,000+460,000)/1,000 = 800\n기말재공품 원가 = 300×800 = 240,000","c":"상"},"관세사2022_39-74":{"w":"정상감손은 환산량에 넣지 않는 비분리계산법으로 가중평균법을 적용하면\n재료 환산량 = 6,000 + 1,800 = 7,800, 전환원가 환산량 = 6,000 + 1,800×40% = 6,720\n재료 단위원가 = (250,000+1,200,000)/7,800 = 185.9, 전환원가 단위원가 = (300,000+800,000)/6,720 = 163.7\n합산하면 약 350이 되어 선지 ③ 360과 차이가 난다. 비례적 감손의 환산량 처리가 선지와 어떻게 맞는지 확인하지 못했다.","c":"하"},"관세사2023_40-71":{"w":"선입선출법이며 최종공정이라 전공정원가는 공정초, 직접재료는 50% 시점, 전환원가는 균등 발생이다.\n환산량(선입선출): 전공정 = 400 + 200 - 100 = 500, 직접재료 = 400 + 200 = 600(기초 40%는 50% 시점 전이라 재료 미투입), 전환원가 = 400 + 200×80% - 100×40% = 520\n단위원가: 전공정 40,000/500 = 80, 재료 6,000/600 = 10, 전환 26,000/520 = 50\n완성품원가 = 기초 10,000 + 전공정 (400-100)×80 + 재료 400×10 + 전환 (400-40)×50 = 10,000 + 24,000 + 4,000 + 18,000 = 56,000","c":"상"},"관세사2024_41-72":{"w":"검사가 공정의 10% 시점이다. 기초재공품(완성도 20%)과 기말재공품(60%)은 모두 검사 시점을 지났다.\n물량 확인: 2,000 + 3,000 = 4,000(완성) + 500(공손) + 500(기말)\n당기에 검사를 통과한 수량 = 완성 4,000 + 기말 500 - 기초 2,000 = 2,500단위\n정상공손수량 = 2,500×5% = 125단위","c":"중"},"관세사2025_42-72":{"w":"선입선출법 가공원가 환산량 = 완성품 4,200 - 기초 500×40% + 기말 800×50% = 4,000 + 400 = 4,400\n당기 가공원가 88,000/4,400 = 단위당 20\n기말재공품 가공원가 = 400×20 = 8,000","c":"상"},"관세사2026_43-71":{"w":"공손수량 = 400 + 1,100 - 1,200 - 200 = 100단위. 검사 시점 60%를 기초(70%)와 기말(80%)은 모두 지났으므로 당기에 검사를 통과한 수량은 1,200 + 200 - 400 = 1,000단위\n정상공손 = 1,000×5% = 50단위, 원가 = 50×200 + 50×60%×300 = 10,000 + 9,000 = 19,000\n정상공손원가는 당기에 검사를 통과한 완성분 800단위와 기말재공품 200단위에 배분한다.\n기말재공품 배분액 = 19,000×200/1,000 = 3,800","c":"중"},"관세사2017_34-76":{"w":"2월 현금유입 = 1월 매출 600,000×55% + 2월 매출 450,000×40% = 330,000 + 180,000 = 510,000\n1월 매입액 = 1월 매출원가 420,000 + 1월 말 재고(2월 매출원가 315,000×10% = 31,500) - 기초재고 60,000 = 391,500\n매입대금은 다음 달에 지급하므로 2월 현금유출 391,500\n차이 = 510,000 - 391,500 = 118,500","c":"상"},"관세사2017_34-79":{"w":"⑤가 옳지 않다. 종업원 만족도, 이직률, 종업원 생산성은 학습과 성장 관점의 지표이다.","c":"상"},"관세사2018_35-78":{"w":"3분기 현금유입\n- 3분기 매출 200,000: 현금매출 40% 80,000 + 외상 120,000×60% = 72,000 → 152,000\n- 2분기 외상 300,000×60% = 180,000의 30% = 54,000\n- 1분기 외상 250,000×60% = 150,000의 10% = 15,000\n합계 = 152,000 + 54,000 + 15,000 = 221,000","c":"상"},"관세사2019_36-79":{"w":"연간 생산수량 = 연간 판매 4,500 + 기말재고 450 - 기초재고 300 = 4,650단위","c":"상"},"관세사2020_37-74":{"w":"2분기 제품 생산량 = 목표판매 650 + 기말제품 (3분기 600×10% = 60) - 기초제품 (650×10% = 65) = 645단위\n기초재공품 40단위는 전분기에 재료를 투입했으므로 2분기 착수 = 645 - 40 = 605단위 (기말재공품은 없다고 본다)\n재료 사용량 = 605×2g = 1,210g\n재료 구입량 = 사용 1,210 + 기말 100 - 기초 120 = 1,190g","c":"중"},"관세사2022_39-79":{"w":"①이 옳지 않다. 품질검사 장비의 유지·보수는 평가원가이다. 예방원가는 불량 발생을 막기 위한 설계, 교육, 예방적 유지 활동 등이다.","c":"상"},"관세사2022_39-80":{"w":"5월 직접재료 필요량 = 1,200×2 = 2,400kg\n5월 말 목표재고 = 6월 필요량 3,000kg×5% = 150kg, 5월 초 재고 = 5월 필요량 2,400×5% = 120kg\n구입량 = 2,400 + 150 - 120 = 2,430kg\n구입예산 = 2,430×10 = 24,300","c":"상"},"관세사2023_40-77":{"w":"1월 매출원가 = 120,000/1.2 = 100,000, 2월 매출원가 = 150,000/1.2 = 125,000\n1월 말 재고 = 125,000×30% = 37,500\n1월 매입액 = 100,000 + 37,500 - 25,500 = 112,000\n1월 지급액 = 현금매입 112,000×70% = 78,400 + 전기 외상매입 34,000 = 112,400","c":"상"},"관세사2023_40-78":{"w":"수명주기 전체: 매출 = 1,400단위×100 = 140,000\n변동제조원가 1,400×50 = 70,000, 작업준비원가 (4+5+5회)×1,000 = 14,000\n마케팅·고객서비스 15,000×3년 = 45,000, 연구개발·설계 2,000\n총이익 = 140,000 - 70,000 - 14,000 - 45,000 - 2,000 = 9,000","c":"상"},"관세사2024_41-77":{"w":"1분기 재료 사용량 = 3,000×2 = 6,000kg\n1분기 말 재고 = 2분기 사용량 5,000×2×20% = 2,000kg, 1분기 초 재고 = 1분기 사용량의 20% = 1,200kg\n구입량 = 6,000 + 2,000 - 1,200 = 6,800kg\n구입예산 = 6,800×3 = 20,400","c":"상"},"관세사2024_41-79":{"w":"①이 옳지 않다. 제품수명주기원가계산은 연구개발부터 폐기까지 전 기간의 원가를 보므로 단기가 아니라 장기 의사결정에 유용하다.","c":"상"},"관세사2025_42-79":{"w":"예방원가는 불량을 막기 위한 활동의 원가이다.\n설계엔지니어링 1,500 + 부품 공급업체평가 600 + 종업원 품질교육 1,100 = 3,200\n제품 품질검사 800은 평가원가, 불량재공품 재작업 750은 내부실패원가, 제품보증수리 300은 외부실패원가이다.","c":"상"},"관세사2025_42-80":{"w":"매출원가 = 매출액×80%: 1월 280,000, 2월 336,000, 3월 360,000\n월말재고 = 다음 달 매출원가×30%: 1월 말 100,800, 2월 말 108,000 (1월 초 재고 0)\n1월 매입 = 280,000 + 100,800 = 380,800, 2월 매입 = 336,000 + 108,000 - 100,800 = 343,200\n2월 현금지출 = 2월 매입 50% 171,600 + 1월 매입 30% 114,240 = 285,840 (12월 매입분은 없다)","c":"상"},"관세사2026_43-76":{"w":"제품 생산량 = 판매 36,000 + 기말제품 1,200 - 기초제품 1,000 = 36,200단위\n재공품에 대해 선입선출법을 쓰고 원재료는 공정초에 투입되므로 착수량 = 완성 36,200 + 기말재공품 1,500 - 기초재공품 1,200 = 36,500단위\n원재료 사용량 = 36,500×3 = 109,500kg\n구입량 = 109,500 + 기말 3,500 - 기초 3,000 = 110,000kg","c":"상"},"관세사2026_43-79":{"w":"④가 옳지 않다. 원가기획은 제품원가의 대부분이 제조 이전의 개발·설계 단계에서 결정된다는 점에 주안점을 두고, 그 단계에서 목표원가를 달성하도록 한다. 제조단계에서 고착된다는 설명은 틀리다.","c":"상"},"관세사2017_34-77":{"w":"실제생산량 3,200단위의 표준기계시간 = 3,200×3 = 9,600시간, 기준조업도 9,000시간\n조업도차이 60,000 유리 = (9,600-9,000)×고정배부율 → 고정배부율 100/시간, 고정예산 = 9,000×100 = 900,000\n소비차이 = 실제 1,100,000 - 예산 900,000 = 200,000 불리","c":"상"},"관세사2018_35-80":{"w":"표준직접노동시간 = 4,000단위×5시간 = 20,000시간\n변동제조간접원가 능률차이 = (실제 20,400 - 표준 20,000)×100 = 40,000 불리\n기준조업도 2,000단위×5시간 = 10,000시간, 고정배부율 720,000/10,000 = 72\n고정제조간접원가 조업도차이 = 예산 720,000 - 배부 20,000×72 = -720,000 (유리)","c":"상"},"관세사2019_36-78":{"w":"고정배부율 = 500,000/50,000시간 = 10\n26,000단위의 표준직접노무시간 = 52,000시간, 배부액 520,000\n조업도차이 = 예산 500,000 - 배부액 520,000 = 20,000 유리","c":"상"},"관세사2020_37-76":{"w":"고정제조간접원가 배부율 = 192,000/48,000시간 = 4\n조업도차이 6,000 유리이므로 배부액 = 예산 192,000 + 6,000 = 198,000\n표준직접노무시간 = 198,000/4 = 49,500시간, 실제생산량 = 49,500/2 = 24,750단위","c":"상"},"관세사2023_40-80":{"w":"단위당: 고정예산 판매가 25, 변동원가 10, 실제 판매가 30, 변동원가 20\n①매출가격차이 = (30-25)×110 = 550 유리\n②매출조업도차이 = (110-100)×(25-10) = 150 유리\n③변동원가차이 = 실제 2,200 - 변동예산 1,100 = 1,100 불리\n④변동예산차이 = 변동예산상 영업이익 (110×15-500 = 1,150) - 실제 500 = 650 불리이므로 500 불리가 아니다.\n⑤고정원가 예산차이 = 600-500 = 100 불리","c":"상"},"관세사2024_41-71":{"w":"3월과 4월의 표준이 같다. 단위당 고정배부액을 s, 기준조업도(표준 환산 단위)를 N이라 하자.\n3월: (N-1,000)×s = 500, 4월: (1,500-N)×s = 500 → N = 1,250, s = 2\n고정제조간접원가 예산 = 2×1,250 = 2,500\n4월 소비차이 300 불리 → 실제발생액 = 2,500 + 300 = 2,800","c":"상"},"관세사2026_43-73":{"w":"표준수량 = 1,400×2 = 2,800kg\n실제가격×실제수량 = 1,827,000, 가격차이 58,000 유리이므로 표준가격×실제수량 = 1,827,000 + 58,000 = 1,885,000\n수량차이 65,000 불리이므로 표준가격×표준수량 = 1,885,000 - 65,000 = 1,820,000 → 표준가격 = 1,820,000/2,800 = 650\n실제수량 = 1,885,000/650 = 2,900kg\n실제가격 = 1,827,000/2,900 = 630","c":"상"},"관세사2017_34-78":{"w":"제의를 수락하면\n- 변동원가 절감 (80+24+16)×1,000 = 120,000\n- 회피 가능한 고정제조간접원가 40,000×25% = 10,000\n- 임대수익 30,000\n- 구입원가 140×1,000 = 140,000\n이익 변화 = 120,000 + 10,000 + 30,000 - 140,000 = 20,000 증가","c":"상"},"관세사2019_36-76":{"w":"유휴생산능력 = 10,000 - 8,000 = 2,000단위로 특별주문 1,500단위를 소화할 수 있고, 기존 판매에 영향이 없다. 고정제조간접원가는 관련이 없다.\n제품B 단위당 증분수익 220, 증분원가 = 변동제조원가 100 + 특수장치 30 + 변동판매비 30 = 160\n증분이익 = (220-160)×1,500 = 90,000 증가","c":"상"},"관세사2022_39-76":{"w":"단위당 변동제조원가 = 240,000×50%/100 = 1,200, 단위당 변동판매관리비 = 60,000×50%/100 = 300\n특별주문에서는 변동판매관리비 20%가 발생하지 않으므로 300×80% = 240\n단위당 증분원가 = 1,200 + 240 = 1,440\n증분이익 = (1,800 - 1,440)×50 = 18,000 증가","c":"상"},"관세사2024_41-76":{"w":"제품B의 시간당 공헌이익이 10이므로 단위당 노무시간은 20/10 = 2시간. 제품A는 시간당 공헌이익 15로 더 높다.\n제품A 2,000단위×1시간 = 2,000시간, 공헌이익 30,000\n남은 1,000시간으로 제품B 500단위 (최대 1,000단위 이내), 공헌이익 500×20 = 10,000\n최대공헌이익 = 30,000 + 10,000 = 40,000","c":"상"},"관세사2026_43-77":{"w":"S2를 폐쇄하면 S2 자체의 변동원가 120,000이 절감된다.\nS1은 S2에 용역의 40%를 제공하고 있었으므로 S2가 없으면 S1의 변동원가 195,000 중 40% 78,000도 절감된다.\n절감 총액 = 120,000 + 78,000 = 198,000","c":"중"},"관세사2026_43-78":{"w":"기계시간: 정규시장 수요를 모두 채우면 A 2,000×2 = 4,000시간, B 1,500×3 = 4,500시간, 합 8,500시간이고 유휴 1,500시간이다.\n특별주문 800단위는 2,400시간이 필요해서 900시간이 부족하다.\n기계시간당 공헌이익은 A 100/2 = 50, B 120/3 = 40이므로 B 정규판매 900/3 = 300단위를 포기한다. 포기하는 공헌이익 300×120 = 36,000\n특별주문 단위당 변동원가 = 200 + 160 + 60 + 60 = 480\n최소판매가격 = 480 + 36,000/800 = 525","c":"상"},"관세사2017_34-80":{"w":"생산 2,000단위, 판매 1,600단위이므로 재고가 400단위 늘었다.\n전부원가계산은 고정제조간접원가 600,000을 단위당 300으로 재고에 포함시켜 400단위분 120,000을 이연한다. 고정판매관리비는 두 방법 모두 기간비용이다.\n전부원가계산 영업이익이 변동원가계산보다 120,000 많다.","c":"상"},"관세사2019_36-73":{"w":"20×1년 생산 6,000, 판매 4,000으로 20×1년 말 재고 2,000단위, 20×2년 생산 6,000, 판매 7,000으로 20×2년 말 재고 1,000단위\n고정제조간접원가 단위당 120,000/6,000 = 20\n전부원가계산과 변동원가계산의 영업이익 차이 = 기말재고 고정제조간접원가 1,000×20 - 기초재고 2,000×20 = -20,000\n변동원가계산 영업이익 = 910,000 + 20,000 = 930,000","c":"상"},"관세사2020_37-80":{"w":"변동원가계산과 초변동원가계산의 차이는 재고에 포함되는 직접노무원가·변동제조간접원가이다.\n1분기 말 재고 = 1,000 + 8,000 - 7,000 = 2,000단위, 1분기 단위당 (1,360,000+800,000)/8,000 = 270\n2분기 단위당 (1,500,000+885,000)/9,000 = 265 (선입선출법이므로 기말재고는 2분기 생산분)\n차이 241,750 = 기말재고×265 - 기초재고 2,000×270 → 기말재고×265 = 781,750 → 기말재고 2,950단위","c":"상"},"관세사2022_39-75":{"w":"변동원가계산 영업이익이 전부원가계산보다 62,500 적다는 것은 재고증가분에 고정제조간접원가가 이연되었다는 뜻이다.\n재고 증가 = 3,000 - 2,500 = 500단위, 단위당 고정제조간접원가 = 62,500/500 = 125\n고정제조간접원가 = 125×3,000 = 375,000","c":"상"},"관세사2024_41-74":{"w":"생산 150단위, 판매 100단위로 재고가 50단위 늘었다.\n단위당 고정제조간접원가 = 6,000/150 = 40, 재고에 이연되는 고정제조간접원가 = 50×40 = 2,000\n전부원가계산 영업이익 = 7,500 + 2,000 = 9,500","c":"상"},"관세사2018_35-53":{"w":"이자비용 6,000 중 현금이 나가지 않는 항목이 있다.\n사채할인발행차금 상각 400은 현금 지급이 아니고, 미지급이자 증가 250-220 = 30도 지급하지 않았다.\n현금 지급 이자 = 6,000 - 400 - 30 = 5,570","c":"상"},"관세사2019_36-70":{"w":"영업활동 현금흐름(간접법)\n당기순이익 500 + 감가상각비 200 - 토지처분이익 100 - 매출채권 증가 1,500 + 재고자산 감소 2,500 - 매입채무 감소 900 = 700\n회사채 발행은 재무활동, 기계장치 취득은 투자활동이다.","c":"상"},"관세사2020_37-49":{"w":"영업활동 현금흐름 = 당기순이익 600 + 감가상각비 200 - 유형자산처분이익 300 - 매출채권 증가 400 + 선급비용 감소 200 + 매입채무 증가 100 = 400 유입\n단기차입금 증가는 재무활동이다.","c":"상"},"관세사2022_39-66":{"w":"②가 옳지 않다. 종속기업과 기타 사업에 대한 지배력의 획득 또는 상실에 따른 총현금흐름은 별도로 표시하고 투자활동으로 분류한다.","c":"상"},"관세사2023_40-47":{"w":"건물 처분: 장부금액 5,000-2,000 = 3,000, 처분이익 1,000이므로 처분대가 4,000 (현금유입)\n건물 취득: 기말 건물 9,000 = 기초 10,000 - 처분 5,000 + 취득이므로 취득 4,000 (현금유출)\n순현금유출 = 4,000 - 4,000 = 0\n감가상각누계액 확인: 4,000 - 2,000 + 당기 감가 500 = 2,500","c":"상"},"관세사2024_41-67":{"w":"매입 현금지급액 = 매입액 18,000 + 매입채무 감소 2,000 = 20,000\n매출 현금회수액 = 매출액 20,000 + 매출채권 감소 1,000 = 21,000\n매출원가 = 2,000 + 18,000 - 3,000 = 17,000, 매출총이익 3,000\n순현금유입 = 21,000 - 20,000 = 1,000 (⑤)\n①②③④는 위 금액과 맞지 않는다.","c":"상"},"관세사2024_41-68":{"w":"영업에서 창출된 현금 = 당기순이익 2,500 + 법인세비용 1,000 + 이자비용 600 + 감가상각비 200 + 사채상환손실 250 - 토지처분이익 100 - 매출채권 증가 1,000 + 재고자산 감소 500 + 매입채무 증가 800 = 4,750","c":"상"},"관세사2024_41-70":{"w":"20×2년 사채 상환: 할인차금 200 중 100을 상각한 뒤 상환하므로 상환 직전 장부금액 2,000 - 100 = 1,900, 상환이익 300이므로 상환 지급액 1,900 - 300 = 1,600\n신규 발행: 기말 할인차금 800이 모두 신규 사채의 것이므로 발행 현금 4,000 - 800 = 3,200\n이자비용 600 - 할인차금 상각 100 = 이자 지급 500 (재무활동으로 분류)\n재무활동 순현금흐름 = 3,200 - 1,600 - 500 = 1,100","c":"중"},"관세사2025_42-61":{"w":"⑤가 옳지 않다. 주식이나 기타 지분상품 발행에 따른 현금유입은 재무활동 현금흐름이다.","c":"상"},"관세사2026_43-60":{"w":"ㄱ. 단기매매목적 계약에서 생기는 현금흐름은 영업활동이다.\nㄴ. 외화거래의 현금흐름은 발생일의 환율로 환산한 기능통화 금액으로 기록한다.\nㄷ. 지배력 획득·상실에 따른 총현금흐름은 별도로 표시하고 투자활동으로 분류한다.\nㄹ. 종업원 관련 현금유출은 영업활동이다.\nㅁ. 로열티, 수수료, 중개료 현금유입은 영업활동이다.\n정답은 ㄱ, ㄴ, ㄷ, ㄹ이다.","c":"상"},"관세사2026_43-62":{"w":"대손상각비와 재고자산평가손실은 순액(매출채권·재고자산 순액) 증감에 이미 들어 있어 따로 가산하지 않는다.\n영업에서 창출된 현금 = 세전이익 1,000,000 + 감가상각비 80,000 - 유형자산처분이익 30,000 + 사채상환손실 20,000 + 이자비용 80,000 - 재고자산 증가 40,000 - 매출채권 증가 200,000 - 매입채무 감소 100,000 = 810,000","c":"중"},"관세사2018_35-74":{"w":"균등매출총이익률 30%이므로 각 제품의 총원가(결합원가 배부액 + 추가가공원가)는 매출액의 70%이다.\n제품A 매출액 = 300×30 = 9,000, 총원가 = 9,000×70% = 6,300\n제품A 결합원가 = 6,300 - 추가가공원가 2,100 = 4,200","c":"상"},"관세사2022_39-73":{"w":"결합원가 800,000 중 제품B에 480,000이 배분되었으므로 순실현가치 비율은 A 40% : B 60%이다.\n제품A 순실현가치 = 4,000×250 = 1,000,000 (추가가공 없음, 생산량 기준)이므로 제품B 순실현가치 = 1,000,000×60/40 = 1,500,000\n제품B 6,000×(350 - 단위당 추가가공원가) = 1,500,000 → 350 - x = 250, x = 100","c":"상"},"관세사2023_40-75":{"w":"제품Y 매출액 40×87,500 = 3,500,000\nㄱ 물량기준: Y 배분 1,400,000×40/70 = 800,000, 매출총이익 2,700,000\nㄴ 순실현가치법: X 순실현가치 30×50,000 - 100,000 = 1,400,000, Y 3,500,000이므로 Y 배분 1,400,000×3,500/4,900 = 1,000,000, 매출총이익 2,500,000\nㄷ 균등이익률법: 총매출 5,000,000, 총원가 1,400,000+100,000 = 1,500,000이므로 이익률 70%, Y 원가 3,500,000×30% = 1,050,000, 매출총이익 2,450,000\n따라서 ㄱ > ㄴ > ㄷ","c":"상"},"관세사2024_41-73":{"w":"결합공정에서 완성된 10,000kg에 배분할 결합원가를 먼저 구한다.\n재료원가 200,000×10,000/20,000 = 100,000\n가공원가 300,000 중 완성품 환산량 10,000, 기말재공품 환산량 5,000이므로 300,000×10,000/15,000 = 200,000\n완성품 결합원가 = 300,000\n완성품 10,000kg은 4:1이라 A 8,000kg, B 2,000kg. 판매가치 A 600,000, B 400,000 → B 몫 40%\n제품B 배분액 = 300,000×40% = 120,000","c":"중"},"관세사2025_42-74":{"w":"매출액 A 2,000×200 = 400,000, B 3,000×400 = 1,200,000, 합계 1,600,000\n총원가 = 결합원가 950,000 + 추가가공원가 250,000 = 1,200,000, 균등이익률 = (1,600,000-1,200,000)/1,600,000 = 25%\n제품B 총원가 = 1,200,000×75% = 900,000\n제품B 결합원가 = 900,000 - 250,000 = 650,000","c":"상"},"관세사2019_36-59":{"w":"고객과의 계약에서 생기는 수익의 5단계는 고객과의 계약 식별 → 수행의무 식별 → 거래가격 산정 → 거래가격을 수행의무에 배분 → 수행의무 충족 시 수익 인식이다.","c":"상"},"관세사2020_37-48":{"w":"200개×300 = 60,000을 판매했고 5%(10개)가 반품될 것으로 추정한다.\n환불부채 = 10개×300 = 3,000 (매출은 57,000으로 인식)","c":"상"},"관세사2022_39-61":{"w":"판매 시: 환불부채 = 50개(10%)×100 = 5,000, 매출 45,000, 매출원가 450개×50 = 22,500, 반환제품회수권 2,500\n1월 15일 반품 30개를 환불하고 개당 60에 다시 현금판매: 매출 1,800, 원가 30×50 = 1,500 (반환제품회수권에서 대체)\n매출총이익 = (45,000 - 22,500) + (1,800 - 1,500) = 22,800","c":"중"},"관세사2023_40-43":{"w":"①이 기간에 걸쳐 수행의무를 이행하는 경우이다. 고객이 기업의 수행에서 제공하는 효익을 동시에 얻고 소비하면 기간에 걸쳐 이행한다.\n②~⑤는 한 시점에 이행되는 수행의무에서 통제 이전을 판단하는 지표이다.","c":"상"},"관세사2023_40-48":{"w":"재고자산 판매대금 현재가치 = 20,000×0.9091 + 20,000×0.8264 = 18,182 + 16,528 = 34,710 (현가계수 0.9091, 0.8264 사용; 원문에 계수 표기가 빠져 있다)\n매출총손익 = 34,710 - 35,000 = -290\n이자수익 = 34,710×10% = 3,471\n20×1년 당기순이익 영향 = -290 + 3,471 = 3,181 증가","c":"중"},"관세사2024_41-48":{"w":"⑤가 옳지 않다. 기간에 걸쳐 이행하려면 자산이 기업에 대체 용도가 없으면서 지금까지 수행을 완료한 부분에 대해 지급청구권이 있어야 한다. 지급청구권이 없으면 한 시점에 수익을 인식한다.","c":"상"},"관세사2024_41-50":{"w":"거래가격 20,000을 제품과 포인트의 개별 판매가격 비율로 배분한다.\n제품 배분액 = 20,000×20,000/(20,000+1,800) = 18,349\n20×1년 3월 1일에 인식할 수익은 제품 판매분 18,349이고 포인트 몫 1,651은 계약부채로 남긴다.","c":"상"},"관세사2025_42-66":{"w":"20×2년 말 총공사원가 추정 = 누적 발생 60,000 + 추가소요 15,000 = 75,000, 진행률 60,000/75,000 = 80%\n누적 계약수익 = 100,000×80% = 80,000\n누적 청구액 = 15,000 + 35,000 = 50,000\n누적 수익이 청구액보다 30,000 많으므로 미청구공사(계약자산) 30,000","c":"상"},"관세사2026_43-63":{"w":"하자보증을 따로 살 수 있으므로 별도의 수행의무이다. 거래가격 126,000을 개별 판매가격 비율 115,000:25,000으로 배분한다.\n설비 = 126,000×115/140 = 103,500 (판매 시점 수익)\n보증 = 126,000×25/140 = 22,500, 20×1년 말까지 6개월 중 4개월 경과 (원가투입 14,000/21,000도 2/3) → 22,500×2/3 = 15,000\n20×1년 총수익 = 103,500 + 15,000 = 118,500","c":"상"},"관세사2026_43-70":{"w":"④가 옳지 않다. 고객이 선급했더라도 재화 이전 시점이 고객의 재량에 따르는 경우에는 유의적인 금융요소가 없는 것으로 본다.","c":"상"},"관세사2019_36-72":{"w":"중급자용 스키에 배부된 원가 208,000 중 앞의 세 활동\n절단 70,000/700회×250 = 25,000, 성형 180,000/900대×300 = 60,000, 도색 225,000/1,500시간×600 = 90,000, 합 175,000\n조립활동 배부액 = 208,000 - 175,000 = 33,000\n중급자용 기계작업시간 x: 88,000×x/(100+x+150) = 33,000 → 55x = 8,250 → x = 150시간","c":"상"},"관세사2020_37-79":{"w":"제품B 총제조원가 = 760×500단위 = 380,000\n직접재료원가 150,000 + 연마작업 300×200 = 60,000 + 조립작업 1,000×50 = 50,000 = 260,000\n선반작업원가 = 380,000 - 260,000 = 120,000 → 기계회전수 120,000/150 = 800회","c":"상"},"관세사2023_40-74":{"w":"⑤가 옳지 않다. 묶음(배치) 크기를 키워 묶음 수를 줄여야 묶음수준 활동원가가 줄어든다. 묶음 크기를 줄이면 작업준비 횟수가 늘어 원가가 증가한다.","c":"상"},"관세사2024_41-75":{"w":"활동별 배부율 = 검사 2.0, 처리 3.0, 주문 2.25, 운반 1.6\n제품A 제조간접원가 = 600×2 + 300×3 + 400×2.25 + 700×1.6 = 1,200 + 900 + 900 + 1,120 = 4,120\n제품A 총원가 = 4,000 + 5,000 + 4,120 = 13,120, 단위당 13,120/10 = 1,312","c":"상"},"관세사2025_42-71":{"w":"⑤가 옳지 않다. 조립활동이나 전수조사 품질검사는 제품 한 단위마다 이루어지는 단위수준활동이다. 묶음수준활동은 구매, 작업준비처럼 묶음 단위로 이루어지는 활동이다.","c":"상"},"관세사2020_37-70":{"w":"취득원가 6,600 = 순자산 공정가치 22,000×30%이므로 영업권은 없다.\n지분법이익 = 당기순이익 4,500×30% = 1,350\n건물 공정가치 차이 4,000의 상각 = 4,000/8 = 500, 투자자 몫 150 차감\n무상증자는 지분율과 장부금액에 영향이 없다.\n20×1년 말 장부금액 = 6,600 + 1,350 - 150 = 7,800","c":"상"},"관세사2022_39-63":{"w":"취득원가 30주×5,000 = 150,000\n지분법이익 = 10,000×30% = 3,000 (당기손익)\n중간배당 30주×400 = 12,000은 투자주식 장부금액을 줄일 뿐 수익이 아니다.\n당기손익 = 3,000 이익","c":"상"},"관세사2023_40-51":{"w":"④가 옳지 않다. 유의적인 영향력을 상실하여 지분법 사용을 중단하면, 해당 관계기업의 해외사업장 환산차이 등 이전에 기타포괄손익으로 인식했던 금액은 당기손익으로 재분류한다.","c":"상"},"관세사2023_40-45":{"w":"12/1 회수분 $10,000: 11/1 환율 1,100에서 1,150으로 외환차익 10,000×50 = 500,000\n12/31 미회수 $10,000: 1,100에서 1,200으로 외화환산이익 10,000×100 = 1,000,000\n외환차이 합계 = 500,000 + 1,000,000 = 1,500,000","c":"상"},"관세사2025_42-63":{"w":"외화차입금 장부금액 변동: 기초 150,000 + 신규 차입 200,000 + 환산손실 15,000 - 상환 장부금액 = 기말 300,000\n상환한 부채의 장부금액 = 65,000, 외환차손 8,000을 더한 현금 상환액 = 73,000\n순현금유입 = 신규 차입 200,000 - 상환 73,000 = 127,000","c":"상"},"관세사2026_43-66":{"w":"재평가모형 토지는 공정가치를 측정한 날의 환율로 환산한다. 20×1년 말 장부금액 $2,200×1,040 = 2,288,000\n처분하는 50%의 장부금액 = 1,144,000\n처분대가 $1,200×1,060 = 1,272,000\n유형자산처분이익 = 1,272,000 - 1,144,000 = 128,000","c":"상"},"관세사2025_42-68":{"w":"①이 옳지 않다. 제조자나 판매자인 리스제공자가 금융리스를 체결할 때 부담하는 원가는 리스 개설직접원가가 아니며, 판매이익을 인식하는 시점에 비용으로 인식한다.","c":"상"},"관세사2026_43-68":{"w":"리스부채 = 100,000×3.3872 = 338,720, 20×1년 이자비용 = 338,720×7% = 23,710\n사용권자산 = 리스부채 338,720 + 리스개설직접원가 20,000 = 358,720\n리스기간 종료 시 반환하므로 리스기간 4년에 걸쳐 상각: 358,720/4 = 89,680\n이자비용과 감가상각비 합계 = 23,710 + 89,680 = 113,390","c":"상"},"관세사2025_42-78":{"w":"ㄱ. 자본비용이 증가하면 미래현금흐름의 현재가치가 줄어 순현재가치는 감소한다.\nㄴ. 초기 투자액이 없어도 순현재가치는 계산할 수 있다.\nㄷ. 순현재가치가 0보다 크면 투자안을 선택한다.\nㄹ. 내부수익률은 순현재가치를 0으로 만드는 할인율이다.\nㅁ. 내부수익률법도 화폐의 시간가치를 고려한다.\n정답은 ㄴ, ㄷ, ㄹ이다.","c":"상"}};
